// END GENERATED FONT PRESET RULES

buildStateReady = initializeBuildState();

figma.ui.onmessage = async (message) => {
  if (message.type === "cancel") {
    figma.closePlugin();
    return;
  }

  if (message.type === "ui-ready") {
    await buildStateReady;
    postBuildState();
    return;
  }

  if (message.type === "pick-selected-color") {
    figma.ui.postMessage({
      type: "picked-color",
      requestId: message.requestId,
      ...readSelectedSolidFill(),
    });
    return;
  }

  if (message.type === "validate-fonts") {
    const results = await validateFontRequests(message.requests || [], Boolean(message.strict));
    figma.ui.postMessage({
      type: "font-validation",
      requestId: message.requestId,
      results,
    });
    return;
  }

  if (message.type === "generate-components") {
    await buildStateReady;
    const manifest = readPluginJson(SEMANTIC_MANIFEST_KEY);
    const allowed = ["FOUNDATION_VALID", "COMPONENTS_FAILED"].includes(currentBuildState?.status)
      && !currentBuildState?.cleanupPending
      && manifest?.status === "valid"
      && manifest?.capabilities?.componentReady === true;
    if (!allowed) {
      figma.ui.postMessage({
        type: "error",
        message: "当前 Design System 尚未满足组件生成条件。",
      });
      return;
    }
    figma.ui.postMessage({
      type: "error",
      message: "Step 2 已通过门禁，但组件生成器尚未在本版本中接入。",
    });
    return;
  }

  if (message.type !== "generate") return;

  await buildStateReady;
  let config = null;
  let system = null;
  let manifest = null;
  let validation = { errors: [], warnings: [] };

  if (!canRunFoundationBuild(currentBuildState)) {
    figma.ui.postMessage({
      type: "error",
      message: `当前状态为 ${currentBuildState?.status || "UNKNOWN"}，不能重新生成 Design System。`,
    });
    return;
  }

  try {
    config = normalizeConfig(message.config);
    const issues = [
      ...validateRawInputs(message.config || {}, config),
      ...validateConfig(config),
    ];
    if (issues.length) {
      figma.ui.postMessage({ type: "error", message: issues.join("\n") });
      return;
    }

    const fontPreflight = await runStrictFontPreflight(config);
    if (fontPreflight.blocking.length) {
      figma.ui.postMessage({
        type: "error",
        message: fontPreflight.blocking.map((result) => result.message).filter(Boolean).join("\n"),
        fontValidation: fontPreflight.results,
      });
      return;
    }

    system = buildSystem(config);
    system.fontValidation = fontPreflight;
    await preloadFonts(system.textTokens, fontPreflight.availableFonts);

    const runId = createRunId("foundation");
    currentWriteTracker = createWriteTracker(runId, "FOUNDATION_BUILDING", config.projectCode);
    saveBuildState(currentWriteTracker.state);
    clearSemanticManifest();

    const existing = await scanExisting();
    if (existing.total > 0) await deleteExisting(existing);

    const result = await writeSystem(system);
    const semanticPlan = buildSemanticRolePlan(system);
    const supportsSemanticComponentContract = config.systemType !== "lightweight" && config.colorOutput === "variable";
    const manifestPlan = supportsSemanticComponentContract
      ? semanticPlan
      : {
          ...semanticPlan,
          colorRoles: [],
          resources: { spacing: {}, radius: {}, typography: {}, effects: {} },
    };
    if (supportsSemanticComponentContract) {
      result.semanticVariables = await writeSemanticRoleVariables(semanticPlan, system);
    } else {
      result.semanticVariables = 0;
      validation = {
        errors: [],
        warnings: ["当前生成模式不创建组件语义 Alias；Foundation 可用，但 componentReady=false。"],
      };
    }
    const inventory = await scanDesignSystemInventory(config.projectCode);
    if (supportsSemanticComponentContract) validation = validateSemanticManifest(semanticPlan, inventory, system);
    validation.warnings = uniqueStrings([
      ...(validation.warnings || []),
      ...fontValidationMessages(system),
    ]);
    manifest = buildSemanticManifest(system, manifestPlan, inventory, validation);
    if (validation.errors.length) {
      const error = new Error(`Design System 校验失败：\n${validation.errors.join("\n")}`);
      error.manifest = manifest;
      throw error;
    }

    saveSemanticManifest(manifest);
    const exports = buildDeveloperExportFiles(system, manifest, inventory);
    currentWriteTracker.state = createBuildState("FOUNDATION_VALID", {
      projectCode: config.projectCode,
      runId,
      cleanup: emptyCleanupRecord(),
    });
    saveBuildState(currentWriteTracker.state);
    currentWriteTracker = null;
    figma.ui.postMessage({ type: "success", message: summarizeResult(result), result, exports, manifest });
    figma.notify("Design system generated");
  } catch (error) {
    const messageText = error && error.message ? error.message : String(error);
    if (!currentWriteTracker) {
      figma.ui.postMessage({ type: "error", message: messageText, fontValidation: error?.fontValidation || [] });
      return;
    }
    const cleanup = currentWriteTracker
      ? await cleanupTrackedBuild(currentWriteTracker.state)
      : { errors: [], cleanup: emptyCleanupRecord() };
    const invalidManifest = error?.manifest || buildInvalidSemanticManifest(config, validation, messageText);
    saveSemanticManifest(invalidManifest);
    const failedState = createBuildState("FOUNDATION_INVALID", {
      projectCode: config?.projectCode || currentBuildState?.projectCode || "",
      runId: currentWriteTracker?.runId || currentBuildState?.runId || "",
      lastError: messageText,
      cleanupPending: cleanup.errors.length > 0,
      cleanup: cleanup.cleanup,
    });
    saveBuildState(failedState);
    currentWriteTracker = null;
    const cleanupMessage = cleanup.errors.length
      ? `\n半成品仍有 ${cleanup.errors.length} 项未清理，将在下次启动时继续处理。`
      : "\n本轮半成品已清理。";
    figma.ui.postMessage({ type: "error", message: `生成失败。${cleanupMessage}\n${messageText}` });
  }
};

function createBuildState(status, overrides = {}) {
  return {
    schemaVersion: BUILD_STATE_SCHEMA_VERSION,
    status,
    projectCode: "",
    runId: "",
    lastError: "",
    cleanupPending: false,
    cleanup: emptyCleanupRecord(),
    updatedAt: new Date().toISOString(),
    ...overrides,
  };
}

function emptyCleanupRecord() {
  return {
    collections: [],
    variables: [],
    paintStyles: [],
    textStyles: [],
    effectStyles: [],
    pages: [],
    componentNodes: [],
  };
}

function readPluginJson(key) {
  const raw = figma.root.getPluginData(key);
  if (!raw) return null;
  try {
    return JSON.parse(raw);
  } catch (error) {
    return null;
  }
}

function saveBuildState(state) {
  currentBuildState = { ...state, updatedAt: new Date().toISOString() };
  figma.root.setPluginData(BUILD_STATE_KEY, JSON.stringify(currentBuildState));
  postBuildState();
}

function postBuildState() {
  if (!currentBuildState) return;
  const manifest = readPluginJson(SEMANTIC_MANIFEST_KEY);
  figma.ui.postMessage({
    type: "build-state",
    state: currentBuildState,
    manifest,
    componentGeneratorAvailable: false,
    secondaryLevelSchema: FONT_PRESET_RULES.secondaryUsageSchema || null,
  });
}

function clearSemanticManifest() {
  figma.root.setPluginData(SEMANTIC_MANIFEST_KEY, "");
}

function saveSemanticManifest(manifest) {
  figma.root.setPluginData(SEMANTIC_MANIFEST_KEY, JSON.stringify(manifest));
}

function canRunFoundationBuild(state) {
  if (!state) return true;
  return ["EMPTY", "FOUNDATION_INVALID", "FOUNDATION_VALID", "COMPONENTS_FAILED"].includes(state.status) && !state.cleanupPending;
}

function createRunId(prefix) {
  return `${prefix}-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 10)}`;
}

async function initializeBuildState() {
  const saved = readPluginJson(BUILD_STATE_KEY);
  currentBuildState = saved || createBuildState("EMPTY");
  if (["FOUNDATION_BUILDING", "COMPONENTS_BUILDING"].includes(currentBuildState.status) || currentBuildState.cleanupPending) {
    const interruptedStatus = currentBuildState.status;
    const cleanup = await cleanupTrackedBuild(currentBuildState);
    const foundationInterrupted = ["FOUNDATION_BUILDING", "FOUNDATION_INVALID"].includes(interruptedStatus);
    const nextStatus = foundationInterrupted ? "FOUNDATION_INVALID" : "COMPONENTS_FAILED";
    if (foundationInterrupted) {
      saveSemanticManifest(buildInvalidSemanticManifest(
        { projectCode: currentBuildState.projectCode || "" },
        { errors: ["上一次 Design System 生成意外中断。"], warnings: [] },
        "上一次 Design System 生成意外中断。",
      ));
    }
    saveBuildState(createBuildState(nextStatus, {
      projectCode: currentBuildState.projectCode || "",
      runId: currentBuildState.runId || "",
      lastError: foundationInterrupted ? "上一次 Design System 生成意外中断。" : "上一次组件生成意外中断。",
      cleanupPending: cleanup.errors.length > 0,
      cleanup: cleanup.cleanup,
    }));
  } else {
    saveBuildState(currentBuildState);
  }
  return currentBuildState;
}

function readSelectedSolidFill() {
  const selection = figma.currentPage.selection || [];
  if (!selection.length) {
    return {
      ok: false,
      message: "请先在画布中选中一个带纯色填充的图层。",
    };
  }

  const node = selection[0];
  if (!("fills" in node)) {
    return {
      ok: false,
      message: "当前选中图层没有可读取的填充色。请选择一个纯色填充图层。",
    };
  }

  const fills = node.fills;
  if (fills === figma.mixed) {
    return {
      ok: false,
      message: "当前选中图层的填充是混合状态。请选择单个纯色填充图层。",
    };
  }

  if (!Array.isArray(fills) || fills.length === 0) {
    return {
      ok: false,
      message: "当前选中图层没有填充色。请选择一个纯色填充图层。",
    };
  }

  const firstVisibleFill = fills.find((paint) => paint.visible !== false);
  const firstSolidFill = fills.find((paint) => paint.visible !== false && paint.type === "SOLID");
  if (!firstVisibleFill) {
    return {
      ok: false,
      message: "当前选中图层没有可见填充色。请选择一个纯色填充图层。",
    };
  }

  if (!firstSolidFill) {
    return {
      ok: false,
      message: "请选择纯色图层；当前选中图层没有可读取的纯色填充。",
    };
  }

  return {
    ok: true,
    hex: figmaColorToHex(firstSolidFill.color),
  };
}

function normalizeConfig(input) {
  const lightBackgroundInput = normalizeHex(input.lightBackgroundColor, "");
  const darkBackgroundInput = normalizeHex(input.darkBackgroundColor, "");
  const lightDarkBackgrounds = resolveLightDarkBackgrounds(lightBackgroundInput, darkBackgroundInput);
  const config = {
    projectCode: normalizeProjectCode(input.projectCode),
    rawProjectCode: String(input.projectCode || "").trim(),
    systemType: input.systemType || "standard",
    multiThemeType: input.multiThemeType || "light-dark",
    primaryKind: input.primaryKind || "solid",
    primaryColor: normalizeHex(input.primaryColor, ""),
    primaryGradient: normalizeGradientInput({
      from: input.primaryGradientFrom,
      to: input.primaryGradientTo,
      fallback: input.primaryGradientFallback,
      direction: input.primaryGradientDirection,
    }),
    lightBackgroundColor: lightDarkBackgrounds.light,
    darkBackgroundColor: lightDarkBackgrounds.dark,
    coolBackgroundColor: normalizeHex(input.coolBackgroundColor, "#F6F9FF"),
    warmBackgroundColor: normalizeHex(input.warmBackgroundColor, "#FFF7F0"),
    themeBackgroundStrategy: input.themeBackgroundStrategy || "shared",
    themes: normalizeThemes(input.themes || []),
    themeColors: [],
	    blackColor: normalizeHex(input.blackColor, ""),
	    primaryFont: String(input.primaryFont || "").trim(),
	    secondaryFonts: normalizeSecondaryFonts(input.secondaryFonts || []),
	    backgroundColor: normalizeHex(input.backgroundColor, ""),
    auxColor: normalizeHex(input.auxColor, ""),
    auxColors: normalizeAuxiliaryInputs(input.auxColors || [], input.auxColor),
    semanticSet: input.semanticSet || "full",
    neutralMode: input.neutralMode || "solid",
    colorOutput: input.colorOutput || "variable",
    typographyOutput: normalizeTypographyOutput(input.typographyOutput),
    typographyScale: normalizeTypographyScale(input.typographyScale || input.typePreset),
    visualTemplate: Boolean(input.visualTemplate),
    modules: {
      brand: true,
      neutral: true,
      semantic: input.semanticSet !== "none",
      auxiliary: Boolean(input.auxColor) || Boolean((input.auxColors || []).some((aux) => aux.value || aux.gradientFrom || aux.gradientTo)),
      background: Boolean(
        input.backgroundColor ||
          input.lightBackgroundColor ||
          input.darkBackgroundColor ||
          input.coolBackgroundColor ||
          input.warmBackgroundColor ||
          (input.themes || []).some((theme) => theme.backgroundColor),
      ),
      typography: true,
      radius: true,
      spacing: true,
      shadow: true,
    },
  };

  if (config.primaryKind === "gradient" && config.primaryGradient.fallback) {
    config.primaryColor = config.primaryGradient.fallback;
  }

  config.themes = uniquifyThemeNames(config.themes);
  config.themeColors = config.themes.map((theme) => theme.primaryColor).filter(Boolean);
  if (!config.auxColor && config.auxColors[0]?.value) config.auxColor = config.auxColors[0].value;
  config.modules.auxiliary = Boolean(config.auxColor) || config.auxColors.length > 0 || config.themes.some((theme) => theme.auxiliaryColors.length);

	  if (config.systemType === "lightweight") {
	    config.semanticSet = input.semanticSet || "red-green";
	    config.neutralMode = input.neutralMode || "opacity";
	    config.colorOutput = input.colorOutput || "style";
    config.secondaryFonts = [];
	  }

  if (config.systemType === "multi-theme" && config.multiThemeType === "multi-primary" && config.themeColors.length) {
    config.primaryColor = config.themeColors[0];
    config.modules.auxiliary = Boolean(config.auxColor) || config.auxColors.length > 0 || config.themes.some((theme) => theme.auxiliaryColors.length);
  }

  return config;
}

function normalizeAuxiliaryInputs(auxColors, fallbackAuxColor, limit = 10) {
  const inputs = Array.isArray(auxColors) && auxColors.length
    ? auxColors
    : fallbackAuxColor
      ? [{ name: "aux-1", value: fallbackAuxColor }]
      : [];
  const usedNames = new Set();
  return inputs
    .slice(0, limit)
    .map((aux, index) => {
      const baseName = sanitizeTokenSegment(aux.name || `aux-${index + 1}`) || `aux-${index + 1}`;
      let name = baseName;
      let suffix = 2;
      while (usedNames.has(name)) {
        name = `${baseName}-${suffix}`;
        suffix += 1;
      }
      usedNames.add(name);
      return {
        name,
        kind: ["solid", "gradient"].includes(aux.kind) ? aux.kind : "solid",
        value: normalizeHex(aux.value, ""),
        primaryGradient: normalizeGradientInput({
          from: aux.gradientFrom,
          to: aux.gradientTo,
          direction: aux.gradientDirection,
        }),
      };
    })
    .filter((aux) => aux.value || (aux.primaryGradient.from && aux.primaryGradient.to));
}

function normalizeThemes(themes) {
  return themes
    .map((theme, index) => {
      const primaryGradient = normalizeGradientInput({
        from: theme.gradientFrom,
        to: theme.gradientTo,
        fallback: theme.gradientFallback,
        direction: theme.gradientDirection,
      });
      const primaryKind = theme.primaryKind || "solid";
      return {
        name: sanitizeModeName(theme.name || `Theme ${index + 1}`),
        primaryKind,
        primaryColor: primaryKind === "gradient" ? primaryGradient.fallback : normalizeHex(theme.primaryColor, ""),
        primaryGradient,
        backgroundColor: normalizeHex(theme.backgroundColor, ""),
        auxiliaryColors: normalizeAuxiliaryInputs(theme.auxiliaryColors || [], "", 5),
      };
    })
    .filter((theme) => theme.primaryColor);
}

function normalizeGradientInput(input) {
  return {
    from: normalizeHex(input.from, ""),
    to: normalizeHex(input.to, ""),
    fallback: normalizeHex(input.fallback, ""),
    direction: input.direction || "linear",
  };
		}

function normalizeSecondaryFonts(fonts) {
  return fonts
    .slice(0, 2)
    .map((font) => {
      const rawLevels = Array.isArray(font.levels) ? font.levels : [];
      const levels = [...new Set(rawLevels.filter((level) => ["headline", "subtitle", "body", "caption"].includes(level)))];
      return {
        family: String(font.family || "").trim(),
        levels,
      };
    })
    .filter((font) => font.family);
}

function normalizeTypographyOutput(value) {
  if (value === "variable" || value === "token") return "style";
  if (["style", "token-style"].includes(value)) return value;
  return "style";
}

function normalizeTypographyScale(value) {
  if (value === "large") return "large";
  return "standard";
}

function normalizeProjectCode(value) {
  const compact = String(value || "")
    .trim()
    .toUpperCase()
    .replace(/[\s_-]+/g, "");
  const prefix = RULES.projectCode?.prefix || "OOG";
  return new RegExp(`^${prefix}\\d+$`).test(compact) ? compact : "";
}

function projectVariableName(config, name) {
  return config.projectCode ? `${config.projectCode}/${name}` : name;
}

function validateConfig(config) {
  const issues = [];
  if (!config.projectCode) {
    issues.push(config.rawProjectCode ? "项目代号格式应为 OOG 加数字，例如 OOG505" : "需要项目代号，例如 OOG505");
  }
  if (config.systemType === "multi-theme" && config.multiThemeType === "multi-primary") {
    if (config.themeColors.length < 2) issues.push("多主色至少需要 2 个主题主色");
    const maxAuxCount = Math.max(0, ...config.themes.map((theme) => theme.auxiliaryColors.length));
    for (let auxIndex = 0; auxIndex < maxAuxCount; auxIndex += 1) {
      const hasAnyAux = config.themes.some((theme) => auxiliaryHasAnyValue(theme.auxiliaryColors[auxIndex]));
      const hasEveryAux = config.themes.every((theme) => auxiliaryHasRequiredValue(theme.auxiliaryColors[auxIndex]));
      if (hasAnyAux && !hasEveryAux) {
        issues.push(`多主色的辅助色 ${auxIndex + 1} 需要每个主题都填写，才能跟随主题切换`);
      }
    }
  } else if (!config.primaryColor) {
    issues.push("需要主色");
  }
  if (!config.blackColor) issues.push("需要黑色 / Neutral 基准");
  if (config.blackColor === RULES.forbiddenBlack) issues.push("黑色不能使用 #000000");
	  if (!config.primaryFont) issues.push("需要主字体");
	  config.secondaryFonts.forEach((font, index) => {
	    if (!font.family) issues.push(`副字体 ${index + 1} 需要字体名称`);
	  });
	  return issues;
	}

function auxiliaryHasAnyValue(aux) {
  return Boolean(aux?.value || aux?.primaryGradient?.from || aux?.primaryGradient?.to);
}

function auxiliaryHasRequiredValue(aux) {
  if (!aux) return false;
  if (aux.kind === "gradient") return Boolean(aux.primaryGradient?.from && aux.primaryGradient?.to);
  return Boolean(aux.value);
}

function validateRawInputs(input, config) {
  const issues = [];
  const multiPrimary = config.systemType === "multi-theme" && config.multiThemeType === "multi-primary";
  if (!multiPrimary && input.primaryKind !== "gradient" && input.primaryColor && !hasValidHex(input.primaryColor)) issues.push("主色格式不正确");
  if (!multiPrimary && input.primaryKind === "gradient") {
    validateGradientRaw(input.primaryGradientFrom, input.primaryGradientTo, input.primaryGradientFallback, "主色渐变", issues);
  }
  if (input.blackColor && !hasValidHex(input.blackColor)) issues.push("黑色 / Neutral 基准格式不正确");
  if (input.auxColor && !hasValidHex(input.auxColor)) issues.push("辅助色格式不正确");
  (input.auxColors || []).forEach((aux, index) => {
    const kind = aux.kind || "solid";
    if (kind === "both") {
      issues.push(`辅助色 ${index + 1} 不能同时选择纯色和渐变，请拆成两个辅助色条目`);
      return;
    }
    if (kind !== "gradient" && aux.value && !hasValidHex(aux.value)) issues.push(`辅助色 ${index + 1} 纯色格式不正确`);
    if (kind !== "solid" && (aux.gradientFrom || aux.gradientTo)) {
      if (!hasValidHex(aux.gradientFrom) || !hasValidHex(aux.gradientTo)) issues.push(`辅助色 ${index + 1} 渐变需要填写正确的起点和终点`);
    }
  });
  if (input.backgroundColor && !hasValidHex(input.backgroundColor)) issues.push("背景色格式不正确");
  if (input.lightBackgroundColor && !hasValidHex(input.lightBackgroundColor)) issues.push("浅色背景格式不正确");
  if (input.darkBackgroundColor && !hasValidHex(input.darkBackgroundColor)) issues.push("深色背景格式不正确");
  if (input.coolBackgroundColor && !hasValidHex(input.coolBackgroundColor)) issues.push("冷色背景格式不正确");
  if (input.warmBackgroundColor && !hasValidHex(input.warmBackgroundColor)) issues.push("暖色背景格式不正确");
  if (input.themeBackgroundStrategy === "tone-pair" && (input.coolBackgroundColor || input.warmBackgroundColor) && (!input.coolBackgroundColor || !input.warmBackgroundColor)) {
    issues.push("冷暖双背景需要同时填写冷色背景和暖色背景");
  }
  if (multiPrimary) {
    const hasPerThemeBackground = input.themeBackgroundStrategy === "per-theme" && (input.themes || []).some((theme) => theme.backgroundColor);
    (input.themes || []).forEach((theme, index) => {
      if (theme.primaryKind === "gradient") {
        validateGradientRaw(theme.gradientFrom, theme.gradientTo, theme.gradientFallback, `Theme ${index + 1} 主色渐变`, issues);
      } else if (theme.primaryColor && !hasValidHex(theme.primaryColor)) {
        issues.push(`Theme ${index + 1} 主色格式不正确`);
      }
      (theme.auxiliaryColors || []).forEach((aux, auxIndex) => {
        const kind = aux.kind || "solid";
        if (kind === "both") {
          issues.push(`Theme ${index + 1} 辅助色 ${auxIndex + 1} 不能同时选择纯色和渐变，请拆成两个辅助色条目`);
          return;
        }
        if (kind !== "gradient" && aux.value && !hasValidHex(aux.value)) issues.push(`Theme ${index + 1} 辅助色 ${auxIndex + 1} 纯色格式不正确`);
        if (kind !== "solid" && (aux.gradientFrom || aux.gradientTo)) {
          if (!hasValidHex(aux.gradientFrom) || !hasValidHex(aux.gradientTo)) issues.push(`Theme ${index + 1} 辅助色 ${auxIndex + 1} 渐变需要填写正确的起点和终点`);
        }
      });
      if (hasPerThemeBackground && !theme.backgroundColor) {
        issues.push(`Theme ${index + 1} 需要背景色`);
      }
      if (theme.backgroundColor && !hasValidHex(theme.backgroundColor)) issues.push(`Theme ${index + 1} 背景色格式不正确`);
    });
  }
  return issues;
}

function validateGradientRaw(from, to, fallback, label, issues) {
  if (!from || !to || !fallback) {
    issues.push(`${label}需要起点、终点和代表主色`);
    return;
  }
  if (!hasValidHex(from)) issues.push(`${label}起点格式不正确`);
  if (!hasValidHex(to)) issues.push(`${label}终点格式不正确`);
  if (!hasValidHex(fallback)) issues.push(`${label}代表主色格式不正确`);
}

async function scanExisting() {
  const variables = await getLocalVariables();
  const collections = await getLocalCollections();
  const paintStyles = await getLocalPaintStyles();
  const textStyles = await getLocalTextStyles();
  const effectStyles = await getLocalEffectStyles();
  const pages = figma.root.children.filter((page) => isGeneratedVisualPage(page));

  return {
    variables,
    collections,
    paintStyles,
    textStyles,
    effectStyles,
    pages,
    total:
      variables.length +
      collections.length +
      paintStyles.length +
      textStyles.length +
      effectStyles.length +
      pages.length,
  };
}

function isGeneratedVisualPage(page) {
  const cleanName = String(page?.name || "").trim();
  return isPluginOwned(page) || GENERATED_PAGE_NAMES.has(cleanName);
}

function splitTokenName(name) {
  return normalizeNameParts(String(name || "").split("/"));
}

function normalizeNameParts(parts) {
  return (parts || []).map((part) => String(part || "").trim()).filter(Boolean);
}

async function deleteExisting(existing) {
  existing.variables.forEach((item) => safeRemove(item));
  existing.paintStyles.forEach((item) => safeRemove(item));
  existing.textStyles.forEach((item) => safeRemove(item));
  existing.effectStyles.forEach((item) => safeRemove(item));
  existing.collections.forEach((item) => safeRemove(item));
  await deletePages(existing.pages);
}

async function deletePages(pages) {
  for (const page of pages) {
    try {
      if (figma.root.children.length <= 1) {
        const replacement = figma.createPage();
        replacement.name = "Page 1";
        await setCurrentPage(replacement);
      }
      if (figma.currentPage === page) {
        await setCurrentPage(figma.root.children.find((candidate) => candidate !== page));
      }
      safeRemove(page);
    } catch (error) {
      // Keep generation success visible even if an old visual page cannot be removed.
    }
  }
}

function markPluginOwned(node) {
  if (!node) return;
  if (typeof node.setPluginData === "function") {
    node.setPluginData(PLUGIN_OWNER_KEY, PLUGIN_OWNER_VALUE);
    if (currentWriteTracker?.runId) node.setPluginData(PLUGIN_RUN_KEY, currentWriteTracker.runId);
  }
  if ("description" in node) {
    const current = String(node.description || "");
    node.description = current.includes(PLUGIN_DESCRIPTION_MARKER)
      ? current
      : [current, PLUGIN_DESCRIPTION_MARKER].filter(Boolean).join("\n");
  }
}

function trackCreated(kind, node) {
  if (!currentWriteTracker || !node) return;
  currentWriteTracker[kind].push(node);
  if (currentWriteTracker.state?.cleanup?.[kind] && node.id) {
    currentWriteTracker.state.cleanup[kind].push(node.id);
    saveBuildState(currentWriteTracker.state);
  }
}

function createWriteTracker(runId = "", status = "FOUNDATION_BUILDING", projectCode = "") {
  const state = createBuildState(status, {
    runId,
    projectCode,
    cleanup: emptyCleanupRecord(),
  });
  return {
    runId,
    state,
    collections: [],
    variables: [],
    paintStyles: [],
    textStyles: [],
    effectStyles: [],
    pages: [],
  };
}

async function rollbackWriteTracker(tracker) {
  if (!tracker) return [];
  const errors = [];
  tracker.variables.forEach((item) => removeTrackedResource(item, errors));
  tracker.paintStyles.forEach((item) => removeTrackedResource(item, errors));
  tracker.textStyles.forEach((item) => removeTrackedResource(item, errors));
  tracker.effectStyles.forEach((item) => removeTrackedResource(item, errors));
  for (const page of tracker.pages) {
    if (figma.root.children.length <= 1) continue;
    if (figma.currentPage === page) {
      await setCurrentPage(figma.root.children.find((candidate) => candidate !== page));
    }
    removeTrackedResource(page, errors);
  }
  tracker.collections.forEach((item) => removeTrackedResource(item, errors));
  return errors;
}

function removeTrackedResource(node, errors) {
  try {
    if (node && typeof node.remove === "function" && !node.removed) node.remove();
  } catch (error) {
    errors.push(error && error.message ? error.message : String(error));
  }
}

async function cleanupTrackedBuild(state) {
  const cleanup = state?.cleanup || emptyCleanupRecord();
  const runId = state?.runId || "";
  const idSets = Object.fromEntries(
    Object.entries(emptyCleanupRecord()).map(([kind]) => [kind, new Set(cleanup[kind] || [])]),
  );
  const resources = {
    variables: await getLocalVariables(),
    collections: await getLocalCollections(),
    paintStyles: await getLocalPaintStyles(),
    textStyles: await getLocalTextStyles(),
    effectStyles: await getLocalEffectStyles(),
    pages: [...figma.root.children],
    componentNodes: [],
  };
  const errors = [];
  const remaining = emptyCleanupRecord();
  const removalOrder = ["variables", "paintStyles", "textStyles", "effectStyles", "componentNodes", "pages", "collections"];
  for (const kind of removalOrder) {
    for (const resource of resources[kind] || []) {
      const matchesId = Boolean(resource?.id && idSets[kind].has(resource.id));
      const matchesRun = Boolean(
        runId &&
          resource &&
          typeof resource.getPluginData === "function" &&
          resource.getPluginData(PLUGIN_RUN_KEY) === runId,
      );
      if (!matchesId && !matchesRun) continue;
      try {
        if (kind === "pages") {
          if (figma.root.children.length <= 1) {
            remaining[kind].push(resource.id);
            continue;
          }
          if (figma.currentPage === resource) {
            await setCurrentPage(figma.root.children.find((candidate) => candidate !== resource));
          }
        }
        resource.remove();
      } catch (error) {
        remaining[kind].push(resource.id);
        errors.push(`${kind}:${resource.id}: ${error && error.message ? error.message : String(error)}`);
      }
    }
  }
  return { errors, cleanup: remaining };
}

function safeRemove(node) {
  try {
    if (node && typeof node.remove === "function") node.remove();
  } catch (error) {
    // Keep the original generation error visible.
  }
}

function isPluginOwned(node) {
  return (
    Boolean(node && typeof node.getPluginData === "function" && node.getPluginData(PLUGIN_OWNER_KEY) === PLUGIN_OWNER_VALUE) ||
    Boolean(node && "description" in node && String(node.description || "").includes(PLUGIN_DESCRIPTION_MARKER))
  );
}

async function writeSystem(system) {
  const result = {
    colorVariables: 0,
    colorStyles: 0,
    gradientStyles: 0,
    numberVariables: 0,
    typographyVariables: 0,
    textStyles: 0,
    effectStyles: 0,
    visualNodes: 0,
  };

  if (system.config.colorOutput === "variable") {
    result.colorVariables = await writeColorVariables(system.colorTokens, system.colorModes, system.config);
  } else {
    result.colorStyles = writePaintStyles(system.colorTokens);
  }
  result.gradientStyles = writeGradientStyles(system.gradientTokens);

  if (shouldWriteNumberVariables(system.config)) {
    result.numberVariables = await writeNumberVariables([...system.radiusTokens, ...system.spacingTokens], system.config);
  }
  if (shouldWriteTypographyVariables(system.config)) {
    result.typographyVariables = await writeTypographyVariables(system.textTokens, system.config);
  }
  if (shouldWriteTextStyles(system.config)) {
    result.textStyles = await writeTextStyles(system.textTokens);
  }
  result.effectStyles = writeEffectStyles(system.shadowTokens);

  if (system.config.visualTemplate) {
    result.visualNodes = await createVisualPage(system);
  }

  return result;
}

function buildSemanticRolePlan(system, rules = SEMANTIC_ROLE_RULES) {
  const config = system.config;
  const collectionName = rules.collectionName || "Design System";
  const modeNames = system.colorModes?.length ? [...system.colorModes] : ["Default"];
  const prefix = (path) => projectVariableName(config, path);
  const planErrors = [];
  const sharedBindings = rules.sharedBindings || {};
  const colorRoles = (rules.colorRoles || []).map((rule) => {
    const variableType = rule.variableType || "COLOR";
    const sourcesByMode = Object.fromEntries(modeNames.map((modeName) => [
      modeName,
      semanticSourceLocator(rule, config, modeName, collectionName, prefix, variableType),
    ]));
    const distinctSourceCount = new Set(Object.values(sourcesByMode).map(resourceLocatorIdentity)).size;
    const explicitStrategy = rule.bindingStrategy || "auto";
    if (!['auto', 'direct', 'semantic-alias'].includes(explicitStrategy)) {
      planErrors.push(`语义角色 ${rule.role} 的 bindingStrategy 无效：${explicitStrategy}。`);
    }
    let bindingStrategy = explicitStrategy === "semantic-alias" || rule.sharedBinding
      ? "semantic-alias"
      : explicitStrategy === "direct"
        ? "direct"
        : distinctSourceCount > 1
          ? "semantic-alias"
          : "direct";
    if (bindingStrategy === "direct" && distinctSourceCount > 1) {
      planErrors.push(`语义角色 ${rule.role} 在不同 Mode 使用不同来源，不能强制 direct。`);
      bindingStrategy = "semantic-alias";
    }

    const sharedDefinition = rule.sharedBinding ? sharedBindings[rule.sharedBinding] : null;
    if (rule.sharedBinding && !sharedDefinition) {
      planErrors.push(`语义角色 ${rule.role} 引用了未声明的 sharedBinding：${rule.sharedBinding}。`);
    }
    if (sharedDefinition?.variableType && sharedDefinition.variableType !== variableType) {
      planErrors.push(`sharedBinding ${rule.sharedBinding} 的类型 ${sharedDefinition.variableType} 与角色 ${rule.role} 的类型 ${variableType} 不一致。`);
    }
    const directBinding = Object.values(sourcesByMode)[0] || {
      collectionName,
      variablePath: "",
      variableType,
    };
    const aliasPath = sharedDefinition?.variablePath || rule.variablePath || "";
    const binding = bindingStrategy === "direct"
      ? { ...directBinding }
      : {
          collectionName: sharedDefinition?.collectionName || rule.collectionName || collectionName,
          variablePath: prefix(aliasPath),
          variableType,
        };
    return {
      role: rule.role,
      bindingStrategy,
      binding,
      sourcesByMode,
      sharedBinding: rule.sharedBinding || "",
      variableType,
      scopes: uniqueStrings([...(sharedDefinition?.scopes || []), ...(rule.scopes || [])]),
    };
  });
  const aliasBindings = buildSemanticAliasBindings(colorRoles, planErrors);
  const resourceRules = rules.resources || {};
  return {
    schemaVersion: rules.schemaVersion || MANIFEST_SCHEMA_VERSION,
    profile: rules.profile || "but-v1",
    projectCode: config.projectCode,
    collectionName,
    modeNames,
    colorRoles,
    aliasBindings,
    errors: uniqueStrings(planErrors),
    resources: {
      spacing: Object.fromEntries(
        Object.entries(resourceRules.spacing || {}).map(([role, path]) => [
          role,
          { collectionName, variablePath: prefix(path), variableType: "FLOAT" },
        ]),
      ),
      radius: Object.fromEntries(
        Object.entries(resourceRules.radius || {}).map(([role, path]) => [
          role,
          { collectionName, variablePath: prefix(path), variableType: "FLOAT" },
        ]),
      ),
      typography: Object.fromEntries(
        Object.entries(resourceRules.typography || {}).map(([role, paths]) => [
          role,
          { resourceType: "TEXT_STYLE", stylePath: paths?.[config.typographyScale] || "" },
        ]),
      ),
      effects: Object.fromEntries(
        Object.entries(resourceRules.effects || {}).map(([role, stylePath]) => [
          role,
          { resourceType: "EFFECT_STYLE", stylePath },
        ]),
      ),
    },
  };
}

function semanticSourceLocator(rule, config, modeName, defaultCollectionName, prefix, variableType) {
  const hasModeSources = rule.sourcesByMode && Object.keys(rule.sourcesByMode).length > 0;
  const modeSource = hasModeSources ? rule.sourcesByMode[modeName] ?? rule.sourcesByMode["*"] : null;
  const source = hasModeSources
    ? modeSource ?? ""
    : rule.source ?? rule.sourceByNeutralMode?.[config.neutralMode] ?? "";
  const sourceObject = source && typeof source === "object" ? source : null;
  const sourcePath = sourceObject?.variablePath || sourceObject?.source || source || "";
  return {
    collectionName: sourceObject?.collectionName || rule.sourceCollectionName || defaultCollectionName,
    variablePath: sourcePath ? prefix(sourcePath) : "",
    variableType: sourceObject?.variableType || variableType,
  };
}

function resourceLocatorIdentity(locator) {
  return `${locator?.collectionName || ""}\u0000${locator?.variablePath || ""}\u0000${locator?.variableType || ""}`;
}

function sameModeSourceIdentities(left, right, modeNames) {
  return modeNames.every((modeName) => resourceLocatorIdentity(left?.[modeName]) === resourceLocatorIdentity(right?.[modeName]));
}

function buildSemanticAliasBindings(colorRoles, errors) {
  const bindings = new Map();
  for (const role of colorRoles.filter((item) => item.bindingStrategy === "semantic-alias")) {
    const key = role.sharedBinding ? `shared:${role.sharedBinding}` : `role:${role.role}`;
    const existing = bindings.get(key);
    if (!existing) {
      bindings.set(key, {
        key,
        sharedBinding: role.sharedBinding,
        binding: { ...role.binding },
        sourcesByMode: Object.fromEntries(Object.entries(role.sourcesByMode).map(([modeName, locator]) => [modeName, { ...locator }])),
        scopes: uniqueStrings(role.scopes || []),
        roles: [role.role],
      });
      continue;
    }
    if (resourceLocatorIdentity(existing.binding) !== resourceLocatorIdentity(role.binding)) {
      errors.push(`sharedBinding ${role.sharedBinding} 的绑定身份不一致。`);
    }
    const modeNames = uniqueStrings([...Object.keys(existing.sourcesByMode), ...Object.keys(role.sourcesByMode)]);
    if (!sameModeSourceIdentities(existing.sourcesByMode, role.sourcesByMode, modeNames)) {
      errors.push(`sharedBinding ${role.sharedBinding} 的各 Mode 来源身份不一致。`);
    }
    existing.scopes = uniqueStrings([...existing.scopes, ...(role.scopes || [])]);
    existing.roles.push(role.role);
  }
  return [...bindings.values()];
}

async function writeSemanticRoleVariables(plan) {
  const collections = await getLocalCollections();
  const variables = await getLocalVariables();
  const collectionsByName = groupBy(collections, (item) => item.name);
  const collectionById = new Map(collections.map((collection) => [collection.id, collection]));
  const variablesByLocator = groupBy(variables, (variable) => {
    const collection = collectionById.get(variable.variableCollectionId);
    return resourceLocatorKey(collection?.name || "", variable.name);
  });
  const errors = [...(plan.errors || [])];
  const preparedSources = new Map();
  for (const role of plan.colorRoles) {
    for (const [modeName, locator] of Object.entries(role.sourcesByMode || {})) {
      if (!locator.variablePath) {
        errors.push(`语义角色 ${role.role} 在 Mode ${modeName} 没有配置 Foundation 来源。`);
        continue;
      }
      if (locator.variablePath.split("/").includes("Component")) {
        errors.push(`语义角色 ${role.role} 禁止引用 Component/*：${locator.variablePath}`);
        continue;
      }
      const matches = variablesByLocator.get(resourceLocatorKey(locator.collectionName, locator.variablePath)) || [];
      if (matches.length !== 1) {
        errors.push(`语义角色 ${role.role} 在 Mode ${modeName} 的来源 ${locator.variablePath} 应恰好存在 1 个，实际为 ${matches.length} 个。`);
        continue;
      }
      const source = matches[0];
      if (source.resolvedType !== locator.variableType) {
        errors.push(`语义角色 ${role.role} 在 Mode ${modeName} 的来源类型应为 ${locator.variableType}，实际为 ${source.resolvedType}。`);
        continue;
      }
      const sourceCollection = collectionById.get(source.variableCollectionId);
      const sourceMode = (sourceCollection?.modes || []).find((mode) => mode.name === modeName) || (sourceCollection?.modes || [])[0];
      if (!sourceMode || source.valuesByMode?.[sourceMode.modeId] === undefined) {
        errors.push(`语义角色 ${role.role} 的来源 ${locator.variablePath} 缺少 Mode ${modeName} 的值。`);
        continue;
      }
      preparedSources.set(semanticSourceLookupKey(locator, modeName), source);
    }
  }
  for (const aliasBinding of plan.aliasBindings || []) {
    const collectionMatches = collectionsByName.get(aliasBinding.binding.collectionName) || [];
    if (collectionMatches.length !== 1) {
      errors.push(`Semantic Alias Collection \`${aliasBinding.binding.collectionName}\` 应恰好存在 1 个，实际为 ${collectionMatches.length} 个。`);
    } else if (!sameStringSet(collectionMatches[0].modes.map((mode) => mode.name), plan.modeNames || [])) {
      errors.push(`Semantic Alias Collection \`${aliasBinding.binding.collectionName}\` 的 Mode 与计划不一致。`);
    }
    if (!aliasBinding.binding.variablePath) {
      errors.push(`Semantic Alias ${aliasBinding.roles.join(", ")} 没有配置绑定路径。`);
    }
  }
  if (errors.length) throw new Error(`Semantic Binding 预检查失败：\n${uniqueStrings(errors).join("\n")}`);

  let count = 0;
  for (const aliasBinding of plan.aliasBindings || []) {
    const collection = (collectionsByName.get(aliasBinding.binding.collectionName) || [])[0];
    const variable = await createVariable(aliasBinding.binding.variablePath, collection, aliasBinding.binding.variableType);
    collection.modes.forEach((mode) => {
      const locator = aliasBinding.sourcesByMode[mode.name];
      const source = locator ? preparedSources.get(semanticSourceLookupKey(locator, mode.name)) : null;
      if (!source) throw new Error(`Semantic Alias ${aliasBinding.binding.variablePath} 缺少 Mode ${mode.name} 的已解析来源。`);
      variable.setValueForMode(mode.modeId, figma.variables.createVariableAlias(source));
    });
    if (Array.isArray(aliasBinding.scopes) && "scopes" in variable) {
      try {
        variable.scopes = [...aliasBinding.scopes];
      } catch (error) {
        // Scope is advisory; validation records a warning if Figma rejects it.
      }
    }
    count += 1;
  }
  return count;
}

function semanticSourceLookupKey(locator, modeName) {
  return `${resourceLocatorIdentity(locator)}\u0000${modeName}`;
}

async function scanDesignSystemInventory(projectCode) {
  const collections = await getLocalCollections();
  const variables = await getLocalVariables();
  const paintStyles = await getLocalPaintStyles();
  const textStyles = await getLocalTextStyles();
  const effectStyles = await getLocalEffectStyles();
  const collectionById = new Map(collections.map((collection) => [collection.id, collection]));
  const variableById = new Map(variables.map((variable) => [variable.id, variable]));
  return {
    projectCode,
    collections,
    variables,
    paintStyles,
    textStyles,
    effectStyles,
    collectionById,
    variableById,
    collectionsByName: groupBy(collections, (item) => item.name),
    variablesByLocator: groupBy(variables, (variable) => {
      const collection = collectionById.get(variable.variableCollectionId);
      return resourceLocatorKey(collection?.name || "", variable.name);
    }),
    textStylesByName: groupBy(textStyles, (style) => style.name),
    effectStylesByName: groupBy(effectStyles, (style) => style.name),
  };
}

function validateSemanticManifest(plan, inventory) {
  const errors = [...(plan.errors || [])];
  const warnings = [];
  const collectionMatches = inventory.collectionsByName.get(plan.collectionName) || [];
  if (collectionMatches.length !== 1) {
    errors.push(`Collection \`${plan.collectionName}\` 应恰好存在 1 个，实际为 ${collectionMatches.length} 个。`);
  }
  const collection = collectionMatches[0];
  if (collection) {
    const actualModes = collection.modes.map((mode) => mode.name);
    if (!sameStringSet(actualModes, plan.modeNames)) {
      errors.push(`Mode 不一致：预期 ${plan.modeNames.join(", ")}；实际 ${actualModes.join(", ")}。`);
    }
  }

  for (const role of plan.colorRoles) {
    const binding = role.binding || {};
    const matches = inventory.variablesByLocator.get(resourceLocatorKey(binding.collectionName, binding.variablePath)) || [];
    if (matches.length !== 1) {
      errors.push(`角色 ${role.role} 的绑定应恰好解析到 1 个 Variable，实际为 ${matches.length} 个。`);
      continue;
    }
    const variable = matches[0];
    if (variable.resolvedType !== binding.variableType) {
      errors.push(`角色 ${role.role} 的绑定类型应为 ${binding.variableType}，实际为 ${variable.resolvedType}。`);
    }
    for (const modeName of plan.modeNames) {
      const expectedSource = role.sourcesByMode?.[modeName];
      const sourceMatches = expectedSource
        ? inventory.variablesByLocator.get(resourceLocatorKey(expectedSource.collectionName, expectedSource.variablePath)) || []
        : [];
      if (sourceMatches.length !== 1) {
        errors.push(`角色 ${role.role} 在 Mode ${modeName} 的来源应恰好解析到 1 个 Variable，实际为 ${sourceMatches.length} 个。`);
        continue;
      }
      const source = sourceMatches[0];
      if (source.resolvedType !== expectedSource.variableType) {
        errors.push(`角色 ${role.role} 在 Mode ${modeName} 的来源类型应为 ${expectedSource.variableType}，实际为 ${source.resolvedType}。`);
      }
      const sourceCollection = inventory.collectionById.get(source.variableCollectionId);
      const sourceMode = (sourceCollection?.modes || []).find((mode) => mode.name === modeName) || sourceCollection?.modes?.[0];
      if (!sourceMode || source.valuesByMode?.[sourceMode.modeId] === undefined) {
        errors.push(`角色 ${role.role} 的来源 ${expectedSource.variablePath} 缺少 Mode ${modeName} 的值。`);
      }

      if (role.bindingStrategy === "semantic-alias") {
        const bindingCollection = inventory.collectionById.get(variable.variableCollectionId);
        const mode = (bindingCollection?.modes || []).find((item) => item.name === modeName);
        if (!mode) {
          errors.push(`角色 ${role.role} 的 Semantic Alias 缺少 Mode ${modeName}。`);
          continue;
        }
        const value = variable.valuesByMode?.[mode.modeId];
        if (!value || value.type !== "VARIABLE_ALIAS") {
          errors.push(`角色 ${role.role} 在 Mode ${modeName} 中不是合法 Alias。`);
          continue;
        }
        const aliasResult = validateAliasChain(value.id, mode.modeId, inventory, new Set(), modeName);
        errors.push(...aliasResult.errors.map((message) => `${role.role} / ${modeName}: ${message}`));
        const actualSource = inventory.variableById.get(value.id);
        const actualSourceCollection = actualSource ? inventory.collectionById.get(actualSource.variableCollectionId) : null;
        if (!actualSource || actualSource.name !== expectedSource.variablePath || actualSourceCollection?.name !== expectedSource.collectionName) {
          errors.push(`角色 ${role.role} 在 Mode ${modeName} 中指向了非预期来源。`);
        }
      } else if (resourceLocatorIdentity(binding) !== resourceLocatorIdentity(expectedSource)) {
        errors.push(`角色 ${role.role} 的 direct 绑定与 Mode ${modeName} 来源身份不一致。`);
      }
    }
    const actualScopes = Array.isArray(variable.scopes) ? variable.scopes : [];
    const missingScopes = (role.scopes || []).filter((scope) => !actualScopes.includes(scope));
    if (missingScopes.length) warnings.push(`角色 ${role.role} 缺少推荐 Scope：${missingScopes.join(", ")}。`);
  }

  for (const category of ["spacing", "radius"]) {
    for (const [role, locator] of Object.entries(plan.resources[category] || {})) {
      const matches = inventory.variablesByLocator.get(resourceLocatorKey(locator.collectionName, locator.variablePath)) || [];
      if (matches.length !== 1) {
        errors.push(`资源 ${role} 应恰好解析到 1 个 Variable，实际为 ${matches.length} 个。`);
        continue;
      }
      const variable = matches[0];
      if (variable.resolvedType !== locator.variableType) {
        errors.push(`资源 ${role} 类型应为 ${locator.variableType}，实际为 ${variable.resolvedType}。`);
      }
      const variableCollection = inventory.collectionById.get(variable.variableCollectionId);
      const missingModes = (variableCollection?.modes || []).filter((mode) => variable.valuesByMode?.[mode.modeId] === undefined);
      if (missingModes.length) errors.push(`资源 ${role} 缺少 Mode：${missingModes.map((mode) => mode.name).join(", ")}。`);
    }
  }

  for (const [role, locator] of Object.entries(plan.resources.typography || {})) {
    const matches = inventory.textStylesByName.get(locator.stylePath) || [];
    if (matches.length !== 1) errors.push(`资源 ${role} 应恰好解析到 1 个 Text Style，实际为 ${matches.length} 个。`);
  }
  for (const [role, locator] of Object.entries(plan.resources.effects || {})) {
    const matches = inventory.effectStylesByName.get(locator.stylePath) || [];
    if (matches.length !== 1) errors.push(`资源 ${role} 应恰好解析到 1 个 Effect Style，实际为 ${matches.length} 个。`);
  }

  return { errors: uniqueStrings(errors), warnings: uniqueStrings(warnings) };
}

function validateAliasChain(variableId, modeId, inventory, visited = new Set(), modeName = "") {
  const errors = [];
  if (visited.has(variableId)) return { errors: ["Alias 存在循环引用。"] };
  visited.add(variableId);
  const variable = inventory.variableById.get(variableId);
  if (!variable) return { errors: ["Alias 指向不存在的 Variable。"] };
  if (splitTokenName(variable.name).includes("Component")) errors.push(`Alias 禁止引用 Component/*：${variable.name}`);
  const collection = inventory.collectionById.get(variable.variableCollectionId);
  const mode = modeName
    ? (collection?.modes || []).find((item) => item.name === modeName) || collection?.modes?.[0]
    : (collection?.modes || []).find((item) => item.modeId === modeId) || collection?.modes?.[0];
  const value = mode ? variable.valuesByMode?.[mode.modeId] : undefined;
  if (value === undefined) errors.push(`Alias 来源 ${variable.name} 缺少当前 Mode 的值。`);
  if (value && value.type === "VARIABLE_ALIAS") {
    errors.push(...validateAliasChain(value.id, modeId, inventory, visited, modeName || mode?.name || "").errors);
  }
  return { errors };
}

function buildTypographyManifest(system) {
  const config = system.config;
  const profile = fontProfileForFamily(config.primaryFont);
  const primaryTokens = (system.textTokens || []).filter((token) => token.fontRole === "primary");
  const requiredRoles = ["baseUi", "emphasis", "strong"];
  const optionalRoles = ["reading"];
  const roleToken = (role) => primaryTokens.find((token) => token.weightRole === role);
  const resolvedStyles = Object.fromEntries(
    [...requiredRoles, ...optionalRoles]
      .map((role) => {
        const token = roleToken(role);
        if (!token) return null;
        return [role, {
          requestedWeight: token.requestedWeight,
          requestedStyle: token.requestedStyle,
          resolvedFontName: token.resolvedFontName || null,
          resolutionStatus: token.resolutionStatus || "unavailable",
          wasFallback: Boolean(token.wasFallback),
        }];
      })
      .filter(Boolean),
  );
  const primaryMappings = profile?.mappings?.primary || {};
  const primaryRoles = [...optionalRoles, ...requiredRoles];
  const requiredResolved = requiredRoles.map(roleToken).filter(Boolean).filter((token) => token.resolvedFontName);
  const distinctRequiredStyles = new Set(requiredResolved.map((token) => `${token.resolvedFontName.family}/${token.resolvedFontName.style}`));
  const requiredExactOrAlias = requiredResolved.every((token) => ["exact", "style-alias"].includes(token.resolutionStatus));
  const runtimeUiEligible = requiredResolved.length === requiredRoles.length
    && requiredExactOrAlias
    && distinctRequiredStyles.size === requiredRoles.length;
  const componentReasons = [];
  if (config.systemType === "lightweight") componentReasons.push("lightweight 模式不提供组件所需的完整 Foundation 语义资源");
  if (config.colorOutput !== "variable") componentReasons.push("组件需要 Variable 颜色输出");
  if (config.systemType === "multi-theme" && config.multiThemeType === "light-dark" && config.neutralMode !== "solid") {
    componentReasons.push("明暗主题组件需要实色 Neutral");
  }
  if (!runtimeUiEligible) componentReasons.push("Primary Font 未解析出 Base UI、Emphasis、Strong 三个不同的可加载样式");
  return {
    schemaVersion: "typography-manifest/1.0.0",
    scale: { id: config.typographyScale, version: "1.0.0" },
    primaryFont: {
      family: config.primaryFont,
      profileId: profile?.id || null,
      profileSource: profile?.source?.provider || "runtime",
      profileVersion: profile?.profileVersion || null,
      profileUiEligible: profile?.eligibility?.primaryUiEligible ?? null,
      runtimeUiEligible,
      requiredRoles,
      optionalRoles,
      weightMapping: profile
        ? Object.fromEntries(primaryRoles.map((role) => [role, primaryMappings[role]?.requestedWeight ?? null]))
        : null,
      fontStyleMapping: profile
        ? Object.fromEntries(primaryRoles.map((role) => [role, primaryMappings[role]?.expectedStyle ?? null]))
        : null,
      resolvedStyles,
    },
    secondaryFonts: (config.secondaryFonts || []).map((font) => {
      const secondaryProfile = fontProfileForFamily(font.family);
      const requestedFamilyKey = normalizeFontKey(font.family);
      const tokens = (system.textTokens || []).filter((token) => token.fontRole === "secondary" && normalizeFontKey(token.requestedFamily || token.family) === requestedFamilyKey);
      const skippedTokens = (system.skippedTextTokens || []).filter((token) => token.fontRole === "secondary" && normalizeFontKey(token.requestedFamily || token.family) === requestedFamilyKey);
      return {
        family: font.family,
        profileId: secondaryProfile?.id || null,
        profileSource: secondaryProfile?.source?.provider || "runtime",
        profileVersion: secondaryProfile?.profileVersion || null,
        profileSecondaryEligible: secondaryProfile?.eligibility?.secondaryEligible ?? null,
        requestedLevels: [...font.levels],
        approvedLevels: secondaryProfile?.mappings?.secondary?.recommendedLevels || null,
        runtimeAvailable: tokens.length ? tokens.every((token) => Boolean(token.resolvedFontName)) : null,
        resolvedStyles: tokens.map((token) => ({
          stylePath: token.name,
          requestedStyle: token.requestedStyle,
          resolvedFontName: token.resolvedFontName || null,
          resolutionStatus: token.resolutionStatus || "unavailable",
          wasFallback: Boolean(token.wasFallback),
        })),
        skippedStyles: skippedTokens.map((token) => ({
          stylePath: token.name,
          reasonCode: token.skipReasonCode,
          size: token.size,
          minRecommendedSizePx: token.minRecommendedSizePx,
        })),
      };
    }),
    textStyles: Object.fromEntries([...(system.textTokens || []), ...(system.skippedTextTokens || [])].map((token) => [token.name, {
      fontRole: token.fontRole,
      weightRole: token.weightRole,
      signatureVersion: token.signatureVersion || "text-style-v1",
      signature: token.signature || "",
      canonicalStylePath: token.canonicalStylePath || token.name,
      generated: !token.skipReasonCode && token.generated !== false,
      reasonCode: token.skipReasonCode || null,
    }])),
    usageMapping: buildTypographyUsageMapping(system.textTokens || []),
    componentReady: {
      value: componentReasons.length === 0,
      reasons: componentReasons,
    },
  };
}

function buildTypographyUsageMapping(tokens) {
  const canonicalFor = (path) => tokens.find((token) => token.name === path && !token.skipReasonCode)?.canonicalStylePath || null;
  return Object.fromEntries([
    ["typography.uiLabelSmall", canonicalFor("Caption/C2")],
    ["typography.buttonLabel", canonicalFor("Subtitle/S1")],
    ["typography.tabLabel", canonicalFor("Body/B2")],
  ].filter(([, stylePath]) => Boolean(stylePath)));
}

function fontValidationMessages(system) {
  return uniqueStrings([
    ...((system.fontValidation?.warnings || []).map((result) => result.message)),
    ...((system.skippedTextTokens || []).map((token) => token.skipMessage)),
  ].filter(Boolean));
}

function buildSemanticManifest(system, plan, inventory, validation) {
  const snapshot = buildActualResourceSnapshot(inventory, system.config.projectCode);
  const typography = buildTypographyManifest(system);
  return {
    schemaVersion: MANIFEST_SCHEMA_VERSION,
    generatorVersion: GENERATOR_VERSION,
    rulesVersion: plan.schemaVersion,
    revisionAlgorithmVersion: REVISION_ALGORITHM_VERSION,
    profile: plan.profile,
    projectCode: system.config.projectCode,
    status: validation.errors.length ? "invalid" : "valid",
    modeNames: [...plan.modeNames],
    generatedAt: new Date().toISOString(),
    configFingerprint: computeRevision(normalizeConfigForFingerprint(system.config)),
    systemRevision: computeRevision(snapshot),
    capabilities: {
      componentReady: validation.errors.length === 0 && typography.componentReady.value,
    },
    typography,
    resources: {
      colors: Object.fromEntries(plan.colorRoles.map((role) => [role.role, {
        bindingStrategy: role.bindingStrategy,
        binding: { ...role.binding },
        sourcesByMode: Object.fromEntries(
          Object.entries(role.sourcesByMode || {}).map(([modeName, locator]) => [modeName, { ...locator }]),
        ),
        ...(role.sharedBinding ? { sharedBinding: role.sharedBinding } : {}),
      }])),
      spacing: plan.resources.spacing,
      radius: plan.resources.radius,
      typography: plan.resources.typography,
      effects: plan.resources.effects,
    },
    validation: {
      errors: [...validation.errors],
      warnings: [...validation.warnings],
    },
  };
}

function buildInvalidSemanticManifest(config, validation = {}, message = "") {
  const errors = uniqueStrings([...(validation.errors || []), message].filter(Boolean));
  return {
    schemaVersion: MANIFEST_SCHEMA_VERSION,
    generatorVersion: GENERATOR_VERSION,
    rulesVersion: SEMANTIC_ROLE_RULES.schemaVersion || MANIFEST_SCHEMA_VERSION,
    revisionAlgorithmVersion: REVISION_ALGORITHM_VERSION,
    profile: SEMANTIC_ROLE_RULES.profile || "but-v1",
    projectCode: config?.projectCode || "",
    status: "invalid",
    modeNames: [],
    generatedAt: new Date().toISOString(),
    configFingerprint: config?.projectCode ? computeRevision(normalizeConfigForFingerprint(config)) : "",
    systemRevision: "",
    resources: { colors: {}, spacing: {}, radius: {}, typography: {}, effects: {} },
    capabilities: { componentReady: false },
    typography: null,
    validation: { errors, warnings: [...(validation.warnings || [])] },
  };
}

function buildActualResourceSnapshot(inventory, projectCode) {
  const projectPrefix = `${projectCode}/`;
  const variables = inventory.variables
    .filter((variable) => variable.name.startsWith(projectPrefix))
    .map((variable) => {
      const collection = inventory.collectionById.get(variable.variableCollectionId);
      return {
        collectionName: collection?.name || "",
        variablePath: variable.name,
        variableType: variable.resolvedType,
        scopes: [...(variable.scopes || [])].sort(),
        valuesByMode: Object.fromEntries(
          [...(collection?.modes || [])]
            .sort((left, right) => left.name.localeCompare(right.name))
            .map((mode) => [mode.name, normalizeVariableValue(variable.valuesByMode?.[mode.modeId], inventory, mode.name)]),
        ),
      };
    })
    .sort(compareResourcePath);
  const textStyles = inventory.textStyles
    .filter((style) => isPluginOwned(style))
    .map((style) => ({
      stylePath: style.name,
      fontName: normalizeStableValue(style.fontName),
      fontSize: normalizeStableValue(style.fontSize),
      lineHeight: normalizeStableValue(style.lineHeight),
      letterSpacing: normalizeStableValue(style.letterSpacing),
      paragraphSpacing: normalizeStableValue(style.paragraphSpacing),
    }))
    .sort(compareStylePath);
  const effectStyles = inventory.effectStyles
    .filter((style) => isPluginOwned(style))
    .map((style) => ({ stylePath: style.name, effects: normalizeStableValue(style.effects || []) }))
    .sort(compareStylePath);
  const paintStyles = inventory.paintStyles
    .filter((style) => isPluginOwned(style))
    .map((style) => ({ stylePath: style.name, paints: normalizeStableValue(style.paints || []) }))
    .sort(compareStylePath);
  return { variables, textStyles, effectStyles, paintStyles };
}

function normalizeVariableValue(value, inventory, modeName = "") {
  if (value && value.type === "VARIABLE_ALIAS") {
    const target = inventory.variableById.get(value.id);
    const collection = target ? inventory.collectionById.get(target.variableCollectionId) : null;
    return {
      type: "VARIABLE_ALIAS",
      collectionName: collection?.name || "",
      variablePath: target?.name || "",
      resolvedValue: normalizeStableValue(resolveVariableValueByMode(target, modeName, inventory)),
    };
  }
  return normalizeStableValue(value);
}

function normalizeStableValue(value) {
  if (typeof value === "number") return Number(value.toFixed(6));
  if (Array.isArray(value)) return value.map(normalizeStableValue);
  if (value && typeof value === "object") {
    return Object.fromEntries(
      Object.keys(value).sort().map((key) => [key, normalizeStableValue(value[key])]),
    );
  }
  return value === undefined ? null : value;
}

function normalizeConfigForFingerprint(config) {
  return normalizeStableValue({
    projectCode: config.projectCode,
    systemType: config.systemType,
    multiThemeType: config.multiThemeType,
    primaryKind: config.primaryKind,
    primaryColor: config.primaryColor,
    primaryGradient: config.primaryGradient,
    lightBackgroundColor: config.lightBackgroundColor,
    darkBackgroundColor: config.darkBackgroundColor,
    themes: config.themes,
    blackColor: config.blackColor,
    primaryFont: config.primaryFont,
    secondaryFonts: config.secondaryFonts,
    semanticSet: config.semanticSet,
    neutralMode: config.neutralMode,
    colorOutput: config.colorOutput,
    typographyOutput: config.typographyOutput,
    typographyScale: config.typographyScale,
  });
}

function computeRevision(value) {
  const input = stableStringify(value);
  let hash = 0x811c9dc5;
  for (let index = 0; index < input.length; index += 1) {
    hash ^= input.charCodeAt(index);
    hash = Math.imul(hash, 0x01000193);
  }
  return `fnv1a32-${(hash >>> 0).toString(16).padStart(8, "0")}`;
}

function stableStringify(value) {
  return JSON.stringify(normalizeStableValue(value));
}

function groupBy(items, keyForItem) {
  const result = new Map();
  for (const item of items || []) {
    const key = keyForItem(item);
    if (!result.has(key)) result.set(key, []);
    result.get(key).push(item);
  }
  return result;
}

function resourceLocatorKey(collectionName, path) {
  return `${collectionName}\u0000${path}`;
}

function sameStringSet(left, right) {
  return [...left].sort().join("\u0000") === [...right].sort().join("\u0000");
}

function uniqueStrings(values) {
  return [...new Set((values || []).filter(Boolean))];
}

function compareResourcePath(left, right) {
  return `${left.collectionName}/${left.variablePath}`.localeCompare(`${right.collectionName}/${right.variablePath}`);
}

function compareStylePath(left, right) {
  return String(left.stylePath || "").localeCompare(String(right.stylePath || ""));
}

function shouldWriteNumberVariables(config) {
  return config.systemType !== "lightweight" || config.colorOutput === "variable";
}

function shouldWriteTypographyVariables(config) {
  return config.typographyOutput === "token-style";
}

function shouldWriteTextStyles(config) {
  return config.typographyOutput === "style" || config.typographyOutput === "token-style";
}

async function writeColorVariables(tokens, modeNames, config) {
  const collection = await getOrCreateCollection("Design System");
  const modes = syncCollectionModes(collection, modeNames);
  let count = 0;
  for (const token of tokens) {
    const variable = await createVariable(projectVariableName(config, token.name), collection, "COLOR");
    modes.forEach((mode) => {
      variable.setValueForMode(mode.modeId, paintToVariableValue(tokenValueForMode(token, mode.name)));
    });
    count += 1;
  }
  return count;
}

function syncCollectionModes(collection, modeNames) {
  const desired = modeNames.length ? modeNames : ["Default"];
  const modes = [...collection.modes];
  if (modes[0] && modes[0].name !== desired[0]) {
    if (typeof collection.renameMode === "function") {
      collection.renameMode(modes[0].modeId, desired[0]);
    }
    modes[0] = { ...modes[0], name: desired[0] };
  }
  desired.slice(1).forEach((name) => {
    if (!modes.some((mode) => mode.name === name)) {
      const modeId = collection.addMode(name);
      modes.push({ modeId, name });
    }
  });
  modes.slice().forEach((mode) => {
    if (!desired.includes(mode.name) && typeof collection.removeMode === "function") {
      collection.removeMode(mode.modeId);
      const index = modes.findIndex((item) => item.modeId === mode.modeId);
      if (index >= 0) modes.splice(index, 1);
    }
  });
  return desired.map((name) => modes.find((mode) => mode.name === name)).filter(Boolean);
}

function tokenValueForMode(token, modeName) {
  if (token.valuesByMode && token.valuesByMode[modeName]) return token.valuesByMode[modeName];
  return { value: token.value, opacity: token.opacity };
}

function setVariableForAllModes(variable, collection, value) {
  collection.modes.forEach((mode) => {
    variable.setValueForMode(mode.modeId, value);
  });
}

async function writeNumberVariables(tokens, config) {
  const collection = await getOrCreateCollection("Design System");
  const modeId = collection.modes[0].modeId;
  let count = 0;
  for (const token of tokens) {
    const variable = await createVariable(projectVariableName(config, token.name), collection, "FLOAT");
    setVariableForAllModes(variable, collection, token.value);
    count += 1;
  }
  return count;
}

async function writeTypographyVariables(tokens, config) {
  const collection = await getOrCreateCollection("Design System");
  let count = 0;
  for (const token of tokens) {
    const variables = [
      { name: projectVariableName(config, `Typography/${token.name}/font-family`), value: token.family, type: "STRING" },
      { name: projectVariableName(config, `Typography/${token.name}/font-weight-name`), value: token.weight, type: "STRING" },
      { name: projectVariableName(config, `Typography/${token.name}/font-weight-value`), value: fontWeightValue(token.weight), type: "FLOAT" },
      { name: projectVariableName(config, `Typography/${token.name}/size`), value: token.size },
      { name: projectVariableName(config, `Typography/${token.name}/line`), value: token.line },
      { name: projectVariableName(config, `Typography/${token.name}/spacing`), value: token.spacing || 0 },
    ];
    for (const item of variables) {
      const variable = await createVariable(item.name, collection, item.type || "FLOAT", { optional: item.type === "STRING" });
      if (!variable) continue;
      setVariableForAllModes(variable, collection, item.value);
      count += 1;
    }
  }
  return count;
}

function typographyVariableNamesForTokens(tokens, config) {
  return tokens.flatMap((token) => [
    projectVariableName(config, `Typography/${token.name}/font-family`),
    projectVariableName(config, `Typography/${token.name}/font-weight-name`),
    projectVariableName(config, `Typography/${token.name}/font-weight-value`),
    projectVariableName(config, `Typography/${token.name}/size`),
    projectVariableName(config, `Typography/${token.name}/line`),
    projectVariableName(config, `Typography/${token.name}/spacing`),
  ]);
}

function writePaintStyles(tokens) {
  let count = 0;
  tokens.forEach((token) => {
    const style = figma.createPaintStyle();
    trackCreated("paintStyles", style);
    style.name = token.name;
    style.paints = [tokenToSolidPaint(token)];
    markPluginOwned(style);
    count += 1;
  });
  return count;
}

function writeGradientStyles(tokens) {
  let count = 0;
  tokens.forEach((token) => {
    const style = figma.createPaintStyle();
    trackCreated("paintStyles", style);
    style.name = token.name;
    style.paints = [gradientToPaint(token)];
    markPluginOwned(style);
    count += 1;
  });
  return count;
}

async function writeTextStyles(tokens) {
  let count = 0;
  const canonicalBySignature = new Map();
  const orderedTokens = [...tokens].sort((left, right) =>
    Number(left.canonicalPriority || 9999) - Number(right.canonicalPriority || 9999) ||
    String(left.name).localeCompare(String(right.name)),
  );
  for (const token of orderedTokens) {
    const fontName = token.resolvedFontName || (await loadFontWithFallback(token.family, token.requestedStyle || token.weight));
    const signature = textStyleSignature(token, fontName);
    token.signatureVersion = "text-style-v1";
    token.signature = signature;
    const canonical = canonicalBySignature.get(signature);
    if (canonical) {
      token.generated = false;
      token.canonicalStylePath = canonical.name;
      continue;
    }

    const style = figma.createTextStyle();
    trackCreated("textStyles", style);
    style.name = token.name;
    style.fontName = fontName;
    style.fontSize = token.size;
    style.lineHeight = { value: token.line, unit: "PIXELS" };
    style.letterSpacing = { value: token.spacing || 0, unit: "PIXELS" };
    if ("textCase" in style) style.textCase = token.textCase || "ORIGINAL";
    if ("textDecoration" in style) style.textDecoration = token.textDecoration || "NONE";
    markPluginOwned(style);
    canonicalBySignature.set(signature, token);
    token.generated = true;
    token.canonicalStylePath = token.name;
    count += 1;
  }
  return count;
}

function textStyleSignature(token, fontName) {
  return stableStringify({
    fontName: {
      family: fontName?.family || token.family || "",
      style: fontName?.style || token.weight || "",
    },
    fontSize: Number(token.size),
    lineHeight: { unit: "PIXELS", value: Number(token.line) },
    letterSpacing: { unit: "PIXELS", value: Number(token.spacing || 0) },
    textCase: token.textCase || "ORIGINAL",
    textDecoration: token.textDecoration || "NONE",
  });
}

function writeEffectStyles(tokens) {
  let count = 0;
  tokens.forEach((token) => {
    const style = figma.createEffectStyle();
    trackCreated("effectStyles", style);
    style.name = token.name;
    style.effects = token.layers.map((layer) => ({
      type: "DROP_SHADOW",
      visible: true,
      color: rgbaToFigmaColor(layer.color),
      offset: { x: layer.x, y: layer.y },
      radius: layer.blur,
      spread: layer.spread,
      blendMode: "NORMAL",
    }));
    markPluginOwned(style);
    count += 1;
  });
  return count;
}

function brandTokens(primary) {
  if (!primary) return [];
  return RULES.brand.map((token) => ({
    name: token.name,
    value: token.source ? primary : mix(primary, colorRef(token.mixWith), token.amount),
  }));
}

function buildSystem(config) {
  const colorModes = config.colorOutput === "variable" ? colorModesForConfig(config) : ["Default"];
  const colorTokens = [];
  const colorTokenSource = config.colorOutput === "variable" ? colorVariableTokensForConfig : colorStyleTokensForConfig;
  colorTokens.push(...colorTokenSource(config, colorModes));
  const allTextTokens = typographyTokens(config);

  return {
    config,
    colorModes,
    colorTokens,
    gradientTokens: gradientTokensForConfig(config),
    radiusTokens: RULES.radius.map((value) => ({ name: `Radius/${value}px`, value })),
    spacingTokens: RULES.spacing.map((value) => ({ name: `Spacing/${value}px`, value })),
    textTokens: allTextTokens.filter((token) => !token.skipReasonCode),
    skippedTextTokens: allTextTokens.filter((token) => token.skipReasonCode),
    shadowTokens: shadowTokens(config),
  };
}

function colorStyleTokensForConfig(config) {
  const colorTokens = [];
  if (config.modules.brand) colorTokens.push(...brandTokensForConfig(config));
  if (config.modules.background) colorTokens.push(...backgroundTokens(config));
  if (config.modules.neutral) colorTokens.push(...neutralTokens(config));
  if (config.modules.semantic) colorTokens.push(...semanticTokens(config));
  if (config.modules.auxiliary) colorTokens.push(...auxiliaryTokensForConfig(config));
  return colorTokens;
}

function colorVariableTokensForConfig(config, modes) {
  const colorTokens = [];
  if (config.modules.brand) colorTokens.push(...brandModeTokens(config, modes));
  if (config.modules.background) colorTokens.push(...backgroundModeTokens(config, modes));
  if (config.modules.neutral) colorTokens.push(...neutralModeTokens(config, modes));
  if (config.modules.semantic) colorTokens.push(...semanticModeTokens(config, modes));
  if (config.modules.auxiliary) colorTokens.push(...auxiliaryModeTokens(config, modes));
  return colorTokens;
}

function colorModesForConfig(config) {
  if (config.systemType === "multi-theme" && config.multiThemeType === "light-dark") return ["Light", "Dark"];
  if (config.systemType === "multi-theme" && config.multiThemeType === "multi-primary") {
    return uniqueNames(config.themes.map((theme, index) => theme.name || `Theme ${index + 1}`));
  }
  return ["Default"];
}

function brandTokensForConfig(config) {
  if (config.systemType === "multi-theme" && config.multiThemeType === "multi-primary") {
    return config.themes.flatMap((theme) => replaceTopPrefix(brandTokens(theme.primaryColor), "Brand", `Brand/${theme.name}`));
  }

  if (config.systemType === "multi-theme" && config.multiThemeType === "light-dark") {
    const darkPrimary = adaptPrimaryForDark(config.primaryColor, config.darkBackgroundColor);
    return [...prefixTokens(brandTokens(config.primaryColor), "Light"), ...prefixTokens(brandTokens(darkPrimary), "Dark")];
  }

  return brandTokens(config.primaryColor);
}

function brandModeTokens(config, modes) {
  if (config.systemType === "multi-theme" && config.multiThemeType === "multi-primary") {
    return modeTokensFromTokenSets(modes.map((mode, index) => [mode, brandTokens(config.themeColors[index] || config.primaryColor)]));
  }
  if (config.systemType === "multi-theme" && config.multiThemeType === "light-dark") {
    const darkPrimary = adaptPrimaryForDark(config.primaryColor, config.darkBackgroundColor);
    return modeTokensFromTokenSets([
      ["Light", brandTokens(config.primaryColor)],
      ["Dark", brandTokens(darkPrimary)],
    ]);
  }
  return brandTokens(config.primaryColor);
}

function gradientTokensForConfig(config) {
  const tokens = [];
  if (config.systemType === "multi-theme" && config.multiThemeType === "multi-primary") {
    tokens.push(...config.themes
      .filter((theme) => theme.primaryKind === "gradient" && theme.primaryGradient.from && theme.primaryGradient.to)
      .map((theme) => ({
        name: `Brand/${theme.name}/primary-gradient`,
        ...theme.primaryGradient,
      })));
    tokens.push(...auxiliaryGradientTokensForConfig(config));
    return tokens;
  }

  if (config.primaryKind === "gradient" && config.primaryGradient.from && config.primaryGradient.to) {
    if (config.systemType === "multi-theme" && config.multiThemeType === "light-dark") {
      tokens.push(
        { name: "Light/Brand/primary-gradient", ...config.primaryGradient },
        { name: "Dark/Brand/primary-gradient", ...adaptGradientForDark(config.primaryGradient, config.darkBackgroundColor) },
      );
      tokens.push(...auxiliaryGradientTokensForConfig(config));
      return tokens;
    }
    tokens.push({ name: "Brand/primary-gradient", ...config.primaryGradient });
  }

  tokens.push(...auxiliaryGradientTokensForConfig(config));
  return tokens;
}

function auxiliaryGradientTokensForConfig(config) {
  const auxList = config.auxColors || [];
  const gradientAux = auxList.filter((aux) => aux.kind === "gradient" && aux.primaryGradient?.from && aux.primaryGradient?.to);
  const perThemeGradientAux =
    config.systemType === "multi-theme" && config.multiThemeType === "multi-primary"
      ? config.themes.flatMap((theme) =>
          theme.auxiliaryColors
            .filter((aux) => aux.kind === "gradient" && aux.primaryGradient?.from && aux.primaryGradient?.to)
            .map((aux) => ({
              name: `Auxiliary/${theme.name}/${aux.name}/gradient`,
              ...aux.primaryGradient,
            })),
        )
      : [];
  if (!gradientAux.length) return perThemeGradientAux;
  if (config.systemType === "multi-theme" && config.multiThemeType === "light-dark") {
    return gradientAux.flatMap((aux, index) => {
      const baseName = gradientAux.length === 1 ? "Auxiliary/gradient" : `Auxiliary/${aux.name}/gradient`;
      return [
        { name: `Light/${baseName}`, ...aux.primaryGradient },
        { name: `Dark/${baseName}`, ...adaptGradientForDark(aux.primaryGradient, config.darkBackgroundColor) },
      ];
    });
  }
  return [
    ...gradientAux.map((aux) => ({
    name: gradientAux.length === 1 ? "Auxiliary/gradient" : `Auxiliary/${aux.name}/gradient`,
    ...aux.primaryGradient,
    })),
    ...perThemeGradientAux,
  ];
}

function adaptGradientForDark(gradient, background) {
  return {
    ...gradient,
    from: adaptPrimaryForDark(gradient.from, background),
    to: adaptPrimaryForDark(gradient.to, background),
    fallback: adaptPrimaryForDark(gradient.fallback, background),
  };
}

function backgroundTokens(config) {
  if (config.systemType === "multi-theme" && config.multiThemeType === "light-dark") {
    return [
      { name: "Light/Background/BG", value: config.lightBackgroundColor },
      { name: "Dark/Background/BG", value: config.darkBackgroundColor },
    ];
  }

  if (config.systemType === "multi-theme" && config.multiThemeType === "multi-primary") {
    if (config.themeBackgroundStrategy === "tone-pair") {
      return [
        { name: "Background/Cool/BG", value: config.coolBackgroundColor },
        { name: "Background/Warm/BG", value: config.warmBackgroundColor },
      ];
    }

    if (config.themeBackgroundStrategy === "per-theme") {
      return config.themes
        .filter((theme) => theme.backgroundColor)
        .map((theme) => ({ name: `Background/${theme.name}/BG`, value: theme.backgroundColor }));
    }
  }

  if (!config.backgroundColor) return [];
  return [{ name: "Background/BG", value: config.backgroundColor }];
}

function backgroundModeTokens(config, modes) {
  if (config.systemType === "multi-theme" && config.multiThemeType === "light-dark") {
    return [
      {
        name: "Background/BG",
        value: config.lightBackgroundColor,
        valuesByMode: {
          Light: { value: config.lightBackgroundColor },
          Dark: { value: config.darkBackgroundColor },
        },
      },
    ];
  }
  if (config.systemType === "multi-theme" && config.multiThemeType === "multi-primary") {
    if (config.themeBackgroundStrategy === "tone-pair") {
      const valuesByMode = Object.fromEntries(
        modes.map((mode, index) => {
          const theme = config.themes[index] || config.themes[0];
          return [mode, { value: backgroundValueForTheme(theme, config) }];
        }),
      );
      return [
        {
          name: "Background/BG",
          value: backgroundValueForTheme(config.themes[0], config),
          valuesByMode,
          visualModeGroups: [
            { name: "Cool", value: config.coolBackgroundColor },
            { name: "Warm", value: config.warmBackgroundColor },
          ],
        },
      ];
    }

    if (config.themeBackgroundStrategy === "per-theme") {
      const valuesByMode = Object.fromEntries(
        modes.map((mode, index) => {
          const theme = config.themes[index] || config.themes[0];
          return [mode, { value: backgroundValueForTheme(theme, config) }];
        }),
      );
      return [
        {
          name: "Background/BG",
          value: backgroundValueForTheme(config.themes[0], config),
          valuesByMode,
        },
      ];
    }
  }
  if (!config.backgroundColor) return [];
  return sameValueModeTokens([{ name: "Background/BG", value: config.backgroundColor }], modes);
}

function backgroundValueForTheme(theme, config) {
  if (!theme) return config.backgroundColor || config.coolBackgroundColor || config.warmBackgroundColor;
  if (config.themeBackgroundStrategy === "per-theme") return theme.backgroundColor || config.backgroundColor;
  if (config.themeBackgroundStrategy === "tone-pair") {
    return backgroundToneForColor(theme.primaryColor) === "warm" ? config.warmBackgroundColor : config.coolBackgroundColor;
  }
  return config.backgroundColor;
}

function backgroundToneForColor(hex) {
  const hue = hexToHsl(hex).h;
  return hue < 90 || hue >= 300 ? "warm" : "cool";
}

function resolveLightDarkBackgrounds(lightInput, darkInput) {
  const fallbackLight = "#F7F8FA";
  const fallbackDark = deriveDarkBackground(fallbackLight);
  if (lightInput && darkInput) return { light: lightInput, dark: darkInput };
  if (lightInput) return { light: lightInput, dark: deriveDarkBackground(lightInput) };
  if (darkInput) return { light: deriveLightBackground(darkInput), dark: darkInput };
  return { light: fallbackLight, dark: fallbackDark };
}

function deriveDarkBackground(lightHex) {
  const rule = RULES.lightDark.backgroundToneMapping.darkFromLight;
  const tone = hexToOklch(lightHex);
  const sourceLightness = clamp(tone.l, 0.88, 0.99);
  const targetLightness = clamp(rule.baseLightness + (0.99 - sourceLightness) * rule.sourceLightnessInfluence, rule.minLightness, rule.maxLightness);
  const targetChroma = clamp(tone.c * rule.chromaMultiplier, 0, rule.maxChroma);
  return oklchToHex({ l: targetLightness, c: targetChroma, h: tone.h });
}

function deriveLightBackground(darkHex) {
  const rule = RULES.lightDark.backgroundToneMapping.lightFromDark;
  const tone = hexToOklch(darkHex);
  const sourceLightness = clamp(tone.l, 0.08, 0.28);
  const targetLightness = clamp(rule.baseLightness - (sourceLightness - 0.08) * rule.sourceLightnessInfluence, rule.minLightness, rule.maxLightness);
  const targetChroma = clamp(tone.c * rule.chromaMultiplier, 0, rule.maxChroma);
  return oklchToHex({ l: targetLightness, c: targetChroma, h: tone.h });
}

function prefixTokens(tokens, prefix) {
  return tokens.map((token) => ({ ...token, name: `${prefix}/${token.name}` }));
}

function replaceTopPrefix(tokens, from, to) {
  return tokens.map((token) => ({ ...token, name: token.name.replace(new RegExp(`^${from}/`), `${to}/`) }));
}

function neutralTokens(config) {
  if (config.systemType === "multi-theme" && config.multiThemeType === "light-dark" && config.neutralMode === "solid") {
    const lightNeutral = solidNeutralTokens(config.blackColor);
    const darkNeutral = solidNeutralTokens(mix(RULES.white, RULES.darkAnchor, 0.82));
    return [...prefixTokens(lightNeutral, "Light"), ...prefixTokens(darkNeutral, "Dark")];
  }

  if (config.neutralMode === "solid") {
    return solidNeutralTokens(config.blackColor);
  }

  const blackSteps = config.systemType === "lightweight" ? RULES.neutral.lightweightBlackOverlay : RULES.neutral.standardOverlay;
  const whiteSteps = config.systemType === "lightweight" ? RULES.neutral.lightweightWhiteOverlay : RULES.neutral.standardOverlay;
  return [
    ...blackSteps.map((step) => ({ name: `Overlay/Black/${step}%`, value: config.blackColor, opacity: step / 100 })),
    ...whiteSteps.map((step) => ({ name: `Overlay/White/${step}%`, value: RULES.white, opacity: step / 100 })),
  ];
}

function neutralModeTokens(config, modes) {
  if (config.neutralMode === "solid" && config.systemType === "multi-theme" && config.multiThemeType === "light-dark") {
    const lightNeutral = solidNeutralTokens(config.blackColor);
    const darkNeutral = solidNeutralTokens(mix(RULES.white, RULES.darkAnchor, 0.82));
    return modeTokensFromTokenSets([
      ["Light", lightNeutral],
      ["Dark", darkNeutral],
    ]);
  }
  return sameValueModeTokens(neutralTokens(config), modes);
}

function solidNeutralTokens(base) {
  return RULES.neutral.solidLevels.map((level, index) => ({
    name: `Neutral/${level}`,
    value: index === 0 ? base : index === RULES.neutral.solidLevels.length - 1 ? RULES.white : mix(base, RULES.white, RULES.neutral.solidMix[index]),
  }));
}

function semanticTokens(config) {
  const mode = config.semanticSet;
  if (mode === "none") return [];
  if (config.systemType === "multi-theme" && config.multiThemeType === "light-dark") {
    const darkPrimary = adaptPrimaryForDark(config.primaryColor, config.darkBackgroundColor);
    return [
      ...prefixTokens(semanticTokensForTone(mode, hexToHsl(config.primaryColor)), "Light"),
      ...prefixTokens(semanticTokensForTone(mode, hexToHsl(darkPrimary)), "Dark"),
    ];
  }

  const tone =
    config.systemType === "multi-theme" && config.multiThemeType === "multi-primary"
      ? averageTone(config.themeColors)
      : hexToHsl(config.primaryColor);
  return semanticTokensForTone(mode, tone);
}

function semanticModeTokens(config, modes) {
  const mode = config.semanticSet;
  if (mode === "none") return [];
  if (config.systemType === "multi-theme" && config.multiThemeType === "light-dark") {
    const darkPrimary = adaptPrimaryForDark(config.primaryColor, config.darkBackgroundColor);
    return modeTokensFromTokenSets([
      ["Light", semanticTokensForTone(mode, hexToHsl(config.primaryColor))],
      ["Dark", semanticTokensForTone(mode, hexToHsl(darkPrimary))],
    ]);
  }
  return sameValueModeTokens(semanticTokens(config), modes);
}

function semanticTokensForTone(mode, tone) {
  return RULES.semantic.baseColors
    .filter((item) => item.groups.includes(mode))
    .flatMap((item) => {
      const tuned = tuneSemanticColor(item.value, tone, item);
      return [
        { name: item.name, value: tuned },
        { name: `${item.name}-10%`, value: tuned, opacity: RULES.semantic.tintOpacity },
      ];
    });
}

function averageTone(colors) {
  const tones = colors.map(hexToHsl);
  return tones.reduce(
    (total, tone, index, list) => ({
      s: total.s + tone.s / list.length,
      l: total.l + tone.l / list.length,
    }),
    { s: 0, l: 0 },
  );
}

function adaptPrimaryForDark(primary, background) {
  const primaryTone = hexToHsl(primary);
  const backgroundTone = hexToHsl(background);
  const targetLightness = clamp(Math.max(primaryTone.l, 0.65 + clamp((0.18 - backgroundTone.l) * 0.22, 0, 0.08)), 0.65, 0.78);
  const targetSaturation = Math.min(primaryTone.s, 0.72);
  return hslToHex({ h: primaryTone.h, s: targetSaturation, l: targetLightness });
}

function tuneSemanticColor(base, themeTone, semanticRule) {
  const baseTone = hexToHsl(base);
  const guard = semanticRule.toneGuard || {};
  const saturation = clamp(baseTone.s + (themeTone.s - baseTone.s) * RULES.semantic.toneFollow.saturation, guard.minSaturation || 0, guard.maxSaturation || 1);
  const lightness = clamp(baseTone.l + (themeTone.l - baseTone.l) * RULES.semantic.toneFollow.lightness, guard.minLightness || 0, guard.maxLightness || 1);
  return hslToHex({ h: baseTone.h, s: saturation, l: lightness });
}

function auxiliaryTokens(aux) {
  const variants = adaptiveAuxiliaryVariants(aux);
  return [
    { name: "Auxiliary/base", value: aux },
    { name: "Auxiliary/02", value: variants[0] },
    { name: "Auxiliary/03", value: variants[1] },
  ];
}

function adaptiveAuxiliaryVariants(aux) {
  const tone = hexToOklch(aux);
  const isLightAuxiliary = tone.l >= 0.82;
  if (isLightAuxiliary) {
    return [
      oklchToHex({
        l: clamp(tone.l - 0.16, 0.7, 0.78),
        c: auxiliaryChroma(tone, 1.8, 0.055, 0.16),
        h: tone.h,
      }),
      oklchToHex({
        l: clamp(tone.l - 0.34, 0.5, 0.62),
        c: auxiliaryChroma(tone, 2.7, 0.085, 0.22),
        h: tone.h,
      }),
    ];
  }
  return [mix(aux, RULES.white, tone.l < 0.45 ? 0.46 : 0.38), mix(aux, RULES.white, tone.l < 0.45 ? 0.78 : 0.72)];
}

function auxiliaryChroma(tone, multiplier, min, max) {
  return clamp(Math.max(tone.c * multiplier, min), 0, max);
}

function auxiliaryTokensForConfig(config) {
  if (config.systemType === "multi-theme" && config.multiThemeType === "multi-primary") {
    const sharedTokens = config.auxColor ? auxiliaryTokens(config.auxColor) : [];
    const themeTokens = config.themes.flatMap((theme) =>
      theme.auxiliaryColors.flatMap((aux) =>
        aux.kind === "solid" && aux.value
          ? replaceTopPrefix(auxiliaryTokens(aux.value), "Auxiliary", `Auxiliary/${theme.name}/${aux.name}`)
          : [],
      ),
    );
    return [...sharedTokens, ...themeTokens];
  }
  if (config.systemType === "multi-theme" && config.multiThemeType === "light-dark") {
    if (!config.auxColor) return [];
    return [
      ...prefixTokens(auxiliaryTokens(config.auxColor), "Light"),
      ...prefixTokens(auxiliaryTokens(adaptAuxiliaryForDark(config.auxColor, config.darkBackgroundColor)), "Dark"),
    ];
  }

  return auxiliaryTokensForAuxList(config);
}

function auxiliaryModeTokens(config, modes) {
  if (config.systemType === "multi-theme" && config.multiThemeType === "multi-primary") {
    const sharedTokens = config.auxColor ? sameValueModeTokens(auxiliaryTokens(config.auxColor), modes) : [];
    return [...sharedTokens, ...perThemeAuxiliaryModeTokens(config, modes)];
  }
  if (config.systemType === "multi-theme" && config.multiThemeType === "light-dark") {
    if (!config.auxColor) return [];
    return modeTokensFromTokenSets([
      ["Light", auxiliaryTokens(config.auxColor)],
      ["Dark", auxiliaryTokens(adaptAuxiliaryForDark(config.auxColor, config.darkBackgroundColor))],
    ]);
  }
  return sameValueModeTokens(auxiliaryTokensForAuxList(config), modes);
}

function auxiliaryTokensForAuxList(config) {
  const auxList = config.auxColors && config.auxColors.length ? config.auxColors : config.auxColor ? [{ name: "aux-1", value: config.auxColor }] : [];
  const solidAuxList = auxList.filter((aux) => aux.kind === "solid" && aux.value);
  if (solidAuxList.length <= 1) return solidAuxList[0]?.value ? auxiliaryTokens(solidAuxList[0].value) : [];
  return solidAuxList.flatMap((aux) => replaceTopPrefix(auxiliaryTokens(aux.value), "Auxiliary", `Auxiliary/${aux.name}`));
}

function adaptAuxiliaryForDark(aux, background) {
  return adaptPrimaryForDark(aux, background);
}

function perThemeAuxiliaryModeTokens(config, modes) {
  const maxAuxCount = Math.max(0, ...config.themes.map((theme) => theme.auxiliaryColors.length));
  const tokens = [];
  for (let auxIndex = 0; auxIndex < maxAuxCount; auxIndex += 1) {
    const slotName = `aux-${auxIndex + 1}`;
    const modeTokenSets = modes.map((modeName, themeIndex) => {
      const theme = config.themes[themeIndex] || config.themes[0];
      const aux = theme?.auxiliaryColors?.[auxIndex];
      const auxValue = aux?.kind === "solid" ? aux.value : "";
      if (!auxValue) return [modeName, []];
      return [modeName, replaceTopPrefix(auxiliaryTokens(auxValue), "Auxiliary", `Auxiliary/${slotName}`)];
    });
    tokens.push(...modeTokensFromTokenSets(modeTokenSets));
  }
  return tokens;
}

function modeTokensFromTokenSets(modeTokenSets) {
  const byName = new Map();
  modeTokenSets.forEach(([modeName, tokens]) => {
    tokens.forEach((token) => {
      if (!byName.has(token.name)) byName.set(token.name, { name: token.name, value: token.value, opacity: token.opacity, valuesByMode: {} });
      byName.get(token.name).valuesByMode[modeName] = { value: token.value, opacity: token.opacity };
    });
  });
  return Array.from(byName.values()).map((token) => {
    const first = Object.values(token.valuesByMode)[0];
    return { ...token, value: first.value, opacity: first.opacity };
  });
}

function sameValueModeTokens(tokens, modes) {
  if (modes.length <= 1) return tokens;
  return tokens.map((token) => ({
    ...token,
    valuesByMode: Object.fromEntries(modes.map((mode) => [mode, { value: token.value, opacity: token.opacity }])),
  }));
}

function typographyTokens(config) {
  const preset = typographyDefinitions(config.typographyScale);
  const profile = fontProfileForFamily(config.primaryFont);
  const primaryTokens = preset.map((definition) => {
    const mapping = primaryFontMapping(definition.weightRole, profile);
    return {
      ...definition,
      fontRole: "primary",
      family: config.primaryFont,
      weightRole: definition.weightRole,
      requestedStyle: mapping.expectedStyle,
      requestedWeight: mapping.requestedWeight,
      styleAliases: [...mapping.styleAliases],
      weight: mapping.expectedStyle,
    };
  });
  if (config.systemType === "lightweight") return primaryTokens;
  return [...primaryTokens, ...config.secondaryFonts.flatMap((font, index) => secondaryTypographyTokens(font, index, preset, config.typographyScale))];
}

function typographyDefinitions(scale) {
  return RULES.typography[normalizeTypographyScale(scale)] || RULES.typography.standard || [];
}

function fontPresetProfiles() {
  return Object.values(FONT_PRESET_RULES.profiles || {});
}

function fontProfileForFamily(family) {
  const target = normalizeFontKey(family);
  return fontPresetProfiles().find((profile) => normalizeFontKey(profile.family) === target) || null;
}

function primaryFontMapping(weightRole, familyOrProfile = null) {
  const profile = typeof familyOrProfile === "string" ? fontProfileForFamily(familyOrProfile) : familyOrProfile;
  const mapping = profile?.mappings?.primary?.[weightRole];
  const fallbackStyle = RULES.typography.weightMapping?.[weightRole] || RULES.typography.weightMapping?.baseUi || "Medium";
  return {
    requestedWeight: mapping?.requestedWeight ?? fontWeightValue(fallbackStyle),
    expectedStyle: mapping?.expectedStyle || fallbackStyle,
    styleAliases: [...(mapping?.styleAliases || [])],
  };
}

function typographyWeightStyle(weightRole, familyOrProfile = null) {
  return primaryFontMapping(weightRole, familyOrProfile).expectedStyle;
}

function secondaryTypographyTokens(font, index, preset, scale = "standard") {
  const prefix = secondaryFontGroupName(font.family, index);
  const levels = Array.isArray(font.levels) ? font.levels : [];
  const profile = fontProfileForFamily(font.family);
  if (profile?.eligibility?.secondaryEligible) {
    return levels.flatMap((level) => secondaryProfileTokens(prefix, font.family, level, profile, scale));
  }
  return manualSecondaryTypographyTokens(prefix, font.family, levels, scale);
}

function secondaryTypographyTokensForProfile(font, index, preset, profile, scale = "standard") {
  const prefix = secondaryFontGroupName(font.family, index);
  const levels = Array.isArray(font.levels) ? font.levels : [];
  return levels.flatMap((level) => secondaryProfileTokens(prefix, font.family, level, profile, scale));
}

function secondaryProfileTokens(prefix, family, level, profile, scale) {
  const mapping = profile?.mappings?.secondary?.[level];
  if (!mapping) return [];
  const definitions = secondaryLevelDefinitions(level, scale);
  return definitions.map((definition) => {
    const token = secondaryToken(`${prefix}/${definition.name}`, family, mapping.expectedStyle, definition.size, definition.line, definition.weightRole);
    token.requestedWeight = mapping.requestedWeight;
    token.styleAliases = [...(mapping.styleAliases || [])];
    token.secondaryLevel = level;
    token.minRecommendedSizePx = mapping.minRecommendedSizePx;
    if (token.size < mapping.minRecommendedSizePx) {
      token.skipReasonCode = "SECONDARY_MIN_SIZE_NOT_MET";
      token.skipMessage = `${token.name} 字号 ${token.size}px 低于 ${family} 的建议下限 ${mapping.minRecommendedSizePx}px。`;
    }
    return token;
  });
}

function manualSecondaryTypographyTokens(prefix, family, levels, scale) {
  return levels.flatMap((level) => secondaryLevelDefinitions(level, scale).map((definition) => {
    const token = secondaryToken(`${prefix}/${definition.name}`, family, typographyWeightStyle(definition.weightRole, family), definition.size, definition.line, definition.weightRole);
    token.secondaryLevel = level;
    return token;
  }));
}

function secondaryLevelDefinitions(level, scale) {
  const normalizedScale = normalizeTypographyScale(scale);
  return (FONT_PRESET_RULES.secondaryUsageSchema?.levels?.[normalizedScale]?.[level] || []).map((definition) => ({ ...definition }));
}

	function secondaryFontGroupName(family, index) {
	  return String(family || `Secondary ${index + 1}`).trim().replace(/[\\/]+/g, "-") || `Secondary ${index + 1}`;
	}

function secondaryToken(name, family, weight, size, line, weightRole = "baseUi") {
  return {
    name,
    family,
    fontRole: "secondary",
	    weight,
	    weightRole,
	    requestedStyle: weight,
	    requestedWeight: fontWeightValue(weight),
	    size,
	    line,
	    spacing: 0,
  };
}

function shadowTokens(config) {
  const source = mix(config.blackColor, RULES.darkAnchor, 0.12);
  return Object.entries(RULES.shadow.styles).map(([name, layers]) => ({
    name,
    layers: layers.map(([x, y, blur, spread, opacity]) => ({
      x,
      y,
      blur,
      spread,
      color: rgbaString(source, opacity),
    })),
  }));
}

async function createVisualPage(system) {
  const page = figma.createPage();
  trackCreated("pages", page);
  page.name = "Design System";
  markPluginOwned(page);
  await setCurrentPage(page);
  const fonts = await visualFonts();

  const frame = figma.createFrame();
  frame.name = "Design System";
  markPluginOwned(frame);
  frame.layoutMode = "VERTICAL";
  frame.itemSpacing = 28;
  frame.paddingTop = 64;
  frame.paddingRight = 64;
  frame.paddingBottom = 64;
  frame.paddingLeft = 64;
  frame.resize(1440, 100);
  frame.counterAxisSizingMode = "FIXED";
  frame.primaryAxisSizingMode = "AUTO";
  frame.fills = [{ type: "SOLID", color: hexToFigmaRgb("#F5F7FA") }];
  page.appendChild(frame);

  await appendVisualHero(frame, system, fonts);
  await appendColorSection(frame, system, fonts);
  await appendTypographySection(frame, system.textTokens, fonts);
  await appendMetricsSection(frame, system, fonts);
  frame.counterAxisSizingMode = "FIXED";
  frame.primaryAxisSizingMode = "AUTO";
  figma.viewport.scrollAndZoomIntoView([frame]);
  return frame.findAll().length + 1;
}

function visualColorTokens(system) {
  const tokens = [];
  system.colorTokens.forEach((token) => {
    if (token.visualModeGroups) {
      token.visualModeGroups.forEach((group) => {
        tokens.push({ ...token, value: group.value, opacity: group.opacity, name: insertTokenSegment(token.name, group.name) });
      });
      return;
    }
    if (!token.valuesByMode || system.colorModes.length <= 1) {
      tokens.push(token);
      return;
    }
    if (modeValuesAreIdentical(token, system.colorModes)) {
      tokens.push(token);
      return;
    }
    system.colorModes.forEach((modeName) => {
      const value = tokenValueForMode(token, modeName);
      tokens.push({ ...token, ...value, name: `${modeName}/${token.name}` });
    });
  });
  return [...tokens, ...system.gradientTokens];
}

function insertTokenSegment(name, segment) {
  const parts = String(name || "").split("/");
  if (parts.length < 2) return `${segment}/${name}`;
  return [parts[0], segment, ...parts.slice(1)].join("/");
}

function modeValuesAreIdentical(token, modes) {
  if (!token.valuesByMode || modes.length <= 1) return true;
  const first = visualModeValueKey(token, modes[0]);
  return modes.every((modeName) => visualModeValueKey(token, modeName) === first);
}

function visualModeValueKey(token, modeName) {
  const value = tokenValueForMode(token, modeName);
  return `${value.value || ""}|${value.opacity ?? ""}`;
}

async function visualFonts() {
  return {
    regular: await loadFontWithFallback("Inter", "Regular"),
    medium: await loadFontWithFallback("Inter", "Medium"),
    semiBold: await loadFontWithFallback("Inter", "Semi Bold"),
  };
}

async function appendVisualHero(parent, system, fonts) {
  const hero = visualFrame("Header", "HORIZONTAL", 1312);
  hero.paddingTop = 32;
  hero.paddingRight = 36;
  hero.paddingBottom = 32;
  hero.paddingLeft = 36;
  hero.itemSpacing = 24;
  hero.counterAxisAlignItems = "CENTER";
  hero.fills = [{ type: "SOLID", color: hexToFigmaRgb("#111827") }];
  hero.cornerRadius = 24;
  parent.appendChild(hero);

  const copy = visualFrame("Header Copy", "VERTICAL", 880);
  copy.itemSpacing = 8;
  copy.fills = [];
  hero.appendChild(copy);

  copy.appendChild(visualText("Design System", fonts.semiBold, 40, 48, "#FFFFFF", 860));
  copy.appendChild(
    visualText(
      `${system.config.systemType} foundations · ${system.colorTokens.length} colors · ${system.textTokens.length} text styles`,
      fonts.medium,
      15,
      22,
      "#AAB2C0",
      860,
    ),
  );

  const badges = visualFrame("System Badges", "HORIZONTAL", 330);
  badges.itemSpacing = 10;
  badges.layoutWrap = "WRAP";
  badges.counterAxisSpacing = 10;
  badges.fills = [];
  hero.appendChild(badges);
  ["Color", "Typography", "Effects", "Spacing"].forEach((item) => {
    badges.appendChild(visualBadge(item, fonts.medium));
  });
}

function visualBadge(text, fontName) {
  const badge = visualFrame(text, "HORIZONTAL", 120);
  badge.counterAxisSizingMode = "AUTO";
  badge.primaryAxisSizingMode = "AUTO";
  badge.paddingTop = 8;
  badge.paddingRight = 12;
  badge.paddingBottom = 8;
  badge.paddingLeft = 12;
  badge.cornerRadius = 999;
  badge.fills = [{ type: "SOLID", color: { r: 1, g: 1, b: 1 }, opacity: 0.1 }];
  badge.appendChild(visualText(text, fontName, 13, 18, "#FFFFFF"));
  return badge;
}

function visualText(text, fontName, size, line, color, width) {
  const node = figma.createText();
  node.name = text;
  node.fontName = fontName;
  node.characters = text;
  node.fontSize = size;
  node.lineHeight = { value: line, unit: "PIXELS" };
  node.fills = [{ type: "SOLID", color: hexToFigmaRgb(color) }];
  if (width) {
    node.textAutoResize = "HEIGHT";
    node.resize(width, line);
  }
  return node;
}

async function appendColorSection(parent, system, fonts) {
  const section = visualPanel("Colors", fonts, "Token palettes grouped by role");
  parent.appendChild(section);
  const tokens = visualColorTokens(system);
  if (system.config.systemType === "multi-theme" && system.config.multiThemeType === "light-dark") {
    appendLightDarkColorGroups(section, tokens, fonts);
    return;
  }
  const groups = groupColorTokens(tokens);
  Object.entries(groups).forEach(([name, groupTokens]) => {
    section.appendChild(colorGroup(name, groupTokens, fonts));
  });
}

function appendLightDarkColorGroups(section, tokens, fonts) {
  const lightTokens = [];
  const darkTokens = [];
  const sharedTokens = [];
  tokens.forEach((token) => {
    if (token.name.startsWith("Light/")) {
      lightTokens.push({ ...token, displayName: token.name.replace(/^Light\//, "") });
      return;
    }
    if (token.name.startsWith("Dark/")) {
      darkTokens.push({ ...token, displayName: token.name.replace(/^Dark\//, "") });
      return;
    }
    sharedTokens.push(token);
  });
  section.appendChild(colorModeGroup("Light Theme", lightTokens, fonts));
  section.appendChild(colorModeGroup("Dark Theme", darkTokens, fonts));
  if (sharedTokens.length) section.appendChild(colorModeGroup("Shared", sharedTokens, fonts));
}

function colorModeGroup(name, tokens, fonts) {
  const wrapper = visualFrame(name, "VERTICAL", 1184);
  wrapper.itemSpacing = 18;
  wrapper.paddingTop = 24;
  wrapper.paddingRight = 24;
  wrapper.paddingBottom = 24;
  wrapper.paddingLeft = 24;
  wrapper.cornerRadius = 18;
  wrapper.strokes = [{ type: "SOLID", color: hexToFigmaRgb("#E4E7EC") }];
  wrapper.fills = [{ type: "SOLID", color: hexToFigmaRgb("#F9FAFB") }];

  const header = visualFrame(`${name} Header`, "HORIZONTAL", 1136);
  header.itemSpacing = 8;
  header.counterAxisAlignItems = "CENTER";
  header.fills = [];
  header.appendChild(visualText(name, fonts.semiBold, 22, 30, "#111827"));
  header.appendChild(visualText(`${tokens.length} tokens`, fonts.medium, 13, 18, "#667085"));
  wrapper.appendChild(header);

  const groups = groupColorTokens(tokens);
  Object.entries(groups).forEach(([groupName, groupTokens]) => {
    wrapper.appendChild(colorGroup(groupName, groupTokens, fonts, 1136));
  });
  return wrapper;
}

function colorGroup(name, tokens, fonts, width = 1184) {
  const group = visualFrame(name, "VERTICAL", width);
  group.itemSpacing = 14;
  group.paddingTop = 18;
  group.paddingRight = 0;
  group.paddingBottom = 20;
  group.paddingLeft = 0;
  group.fills = [];

  const header = visualFrame(`${name} Header`, "HORIZONTAL", width);
  header.itemSpacing = 8;
  header.counterAxisAlignItems = "CENTER";
  header.fills = [];
  header.appendChild(visualText(name, fonts.semiBold, 18, 24, "#1F2937"));
  header.appendChild(visualText(`${tokens.length} tokens`, fonts.medium, 13, 18, "#667085"));
  group.appendChild(header);

  const grid = visualFrame(`${name} Palette`, "HORIZONTAL", width);
  grid.layoutWrap = "WRAP";
  grid.itemSpacing = 14;
  grid.counterAxisSpacing = 14;
  grid.primaryAxisSizingMode = "FIXED";
  grid.fills = [];
  group.appendChild(grid);

  tokens.forEach((token) => grid.appendChild(colorSwatchCard(token, fonts)));
  return group;
}

function colorSwatchCard(token, fonts) {
  const card = visualFrame(token.name, "VERTICAL", 174);
  card.paddingTop = 0;
  card.paddingRight = 0;
  card.paddingBottom = 12;
  card.paddingLeft = 0;
  card.itemSpacing = 10;
  card.cornerRadius = 14;
  card.strokes = [{ type: "SOLID", color: hexToFigmaRgb("#E4E7EC") }];
  card.fills = [{ type: "SOLID", color: hexToFigmaRgb("#FFFFFF") }];

  const swatchWrap = visualFrame("Color", "VERTICAL", 174);
  swatchWrap.resize(174, 92);
  swatchWrap.cornerRadius = 14;
  swatchWrap.fills = [{ type: "SOLID", color: hexToFigmaRgb("#F2F4F7") }];
  const swatch = figma.createRectangle();
  swatch.name = "Fill";
  swatch.resize(174, 92);
  swatch.fills = [token.from && token.to ? gradientToPaint(token) : tokenToSolidPaint(token)];
  swatchWrap.appendChild(swatch);
  card.appendChild(swatchWrap);

  const copy = visualFrame("Details", "VERTICAL", 150);
  copy.itemSpacing = 2;
  copy.paddingRight = 12;
  copy.paddingLeft = 12;
  copy.fills = [];
  copy.appendChild(visualText(shortTokenName(token.displayName || token.name), fonts.semiBold, 12, 16, "#1F2937", 150));
  copy.appendChild(visualText(token.value || `${token.from} -> ${token.to}`, fonts.medium, 11, 16, "#7A8493", 150));
  card.appendChild(copy);
  return card;
}

async function appendTypographySection(parent, tokens, fonts) {
  const section = visualPanel("Typography", fonts, "Text styles with live font previews");
  parent.appendChild(section);

  const table = visualFrame("Typography Table", "VERTICAL", 1184);
  table.itemSpacing = 0;
  table.cornerRadius = 16;
  table.clipsContent = true;
  table.strokes = [{ type: "SOLID", color: hexToFigmaRgb("#E4E7EC") }];
  table.fills = [{ type: "SOLID", color: hexToFigmaRgb("#FFFFFF") }];
  section.appendChild(table);
  table.appendChild(typographyHeader(fonts));

  tokens.forEach((token, index) => {
    table.appendChild(typographyRow(token, fonts, index === tokens.length - 1));
  });
}

function typographyHeader(fonts) {
  const row = visualFrame("Table Header", "HORIZONTAL", 1184);
  row.paddingTop = 14;
  row.paddingRight = 22;
  row.paddingBottom = 14;
  row.paddingLeft = 22;
  row.itemSpacing = 20;
  row.fills = [{ type: "SOLID", color: hexToFigmaRgb("#F9FAFB") }];
  row.appendChild(visualText("Style", fonts.semiBold, 12, 16, "#667085", 190));
  row.appendChild(visualText("Preview", fonts.semiBold, 12, 16, "#667085", 590));
  row.appendChild(visualText("Weight", fonts.semiBold, 12, 16, "#667085", 130));
  row.appendChild(visualText("Size", fonts.semiBold, 12, 16, "#667085", 80));
  row.appendChild(visualText("Line", fonts.semiBold, 12, 16, "#667085", 80));
  return row;
}

function typographyRow(token, fonts, isLast) {
  const row = visualFrame(token.name, "HORIZONTAL", 1184);
  row.paddingTop = 18;
  row.paddingRight = 22;
  row.paddingBottom = 18;
  row.paddingLeft = 22;
  row.itemSpacing = 20;
  row.counterAxisAlignItems = "CENTER";
  row.strokes = isLast ? [] : [{ type: "SOLID", color: hexToFigmaRgb("#EAECF0") }];
  row.strokeBottomWeight = isLast ? 0 : 1;
  row.fills = [{ type: "SOLID", color: hexToFigmaRgb("#FFFFFF") }];

  row.appendChild(visualText(token.name, fonts.semiBold, 14, 20, "#1F2937", 190));
  row.appendChild(visualText("Whereas recognition of the inherent dignity 0123456789", token.resolvedFontName, token.size, token.line, "#1F2937", 590));
  row.appendChild(visualText(token.weight, fonts.medium, 13, 18, "#667085", 130));
  row.appendChild(visualText(String(token.size), fonts.medium, 13, 18, "#667085", 80));
  row.appendChild(visualText(String(token.line), fonts.medium, 13, 18, "#667085", 80));
  return row;
}

async function appendMetricsSection(parent, system, fonts) {
  const section = visualPanel("Metrics", fonts, "Radius, spacing, and elevation foundations");
  parent.appendChild(section);

  const grid = visualFrame("Metrics Grid", "HORIZONTAL", 1184);
  grid.itemSpacing = 16;
  grid.fills = [];
  section.appendChild(grid);
  grid.appendChild(metricCard("Radius", system.radiusTokens, fonts, radiusMetric));
  grid.appendChild(metricCard("Spacing", system.spacingTokens, fonts, spacingMetric));
  grid.appendChild(shadowMetricCard("Shadow", system.shadowTokens, fonts));
}

function metricCard(title, tokens, fonts, renderer) {
  const card = visualFrame(title, "VERTICAL", 384);
  card.itemSpacing = 14;
  card.paddingTop = 22;
  card.paddingRight = 22;
  card.paddingBottom = 22;
  card.paddingLeft = 22;
  card.cornerRadius = 16;
  card.strokes = [{ type: "SOLID", color: hexToFigmaRgb("#E4E7EC") }];
  card.fills = [{ type: "SOLID", color: hexToFigmaRgb("#FFFFFF") }];
  card.appendChild(visualText(title, fonts.semiBold, 18, 24, "#1F2937", 330));
  const list = visualFrame(`${title} List`, "VERTICAL", 330);
  list.itemSpacing = 10;
  list.fills = [];
  card.appendChild(list);
  tokens.forEach((token) => list.appendChild(renderer(token, fonts)));
  return card;
}

function radiusMetric(token, fonts) {
  const row = visualFrame(token.name, "HORIZONTAL", 330);
  row.counterAxisAlignItems = "CENTER";
  row.itemSpacing = 12;
  row.fills = [];
  const sample = figma.createRectangle();
  sample.name = "Radius Sample";
  sample.resize(42, 28);
  sample.cornerRadius = Math.min(token.value, 18);
  sample.fills = [{ type: "SOLID", color: hexToFigmaRgb("#EEF2FF") }];
  sample.strokes = [{ type: "SOLID", color: hexToFigmaRgb("#BFD0FF") }];
  row.appendChild(sample);
  row.appendChild(visualText(token.name, fonts.medium, 13, 18, "#475467", 250));
  return row;
}

function spacingMetric(token, fonts) {
  const row = visualFrame(token.name, "HORIZONTAL", 330);
  row.counterAxisAlignItems = "CENTER";
  row.itemSpacing = 12;
  row.fills = [];
  const sample = figma.createRectangle();
  sample.name = "Spacing Sample";
  sample.resize(Math.max(8, Math.min(token.value * 2, 96)), 10);
  sample.cornerRadius = 999;
  sample.fills = [{ type: "SOLID", color: hexToFigmaRgb("#84CAFF") }];
  row.appendChild(sample);
  row.appendChild(visualText(token.name, fonts.medium, 13, 18, "#475467", 210));
  return row;
}

function shadowMetricCard(title, tokens, fonts) {
  const card = metricCard(title, [], fonts, () => null);
  const list = card.children.find((child) => child.name === `${title} List`);
  tokens.forEach((token) => list.appendChild(shadowMetric(token, fonts)));
  return card;
}

function shadowMetric(token, fonts) {
  const row = visualFrame(token.name, "HORIZONTAL", 330);
  row.counterAxisAlignItems = "CENTER";
  row.itemSpacing = 14;
  row.fills = [];
  const sample = figma.createRectangle();
  sample.name = "Shadow Sample";
  sample.resize(44, 44);
  sample.cornerRadius = 12;
  sample.fills = [{ type: "SOLID", color: hexToFigmaRgb("#FFFFFF") }];
  sample.effects = token.layers.map((layer) => ({
    type: "DROP_SHADOW",
    visible: true,
    color: rgbaToFigmaColor(layer.color),
    offset: { x: layer.x, y: layer.y },
    radius: layer.blur,
    spread: layer.spread,
    blendMode: "NORMAL",
  }));
  row.appendChild(sample);
  row.appendChild(visualText(token.name, fonts.medium, 13, 18, "#475467", 250));
  return row;
}

function visualPanel(title, fonts, subtitle) {
  const panel = visualFrame(title, "VERTICAL", 1312);
  panel.itemSpacing = 24;
  panel.paddingTop = 34;
  panel.paddingRight = 36;
  panel.paddingBottom = 36;
  panel.paddingLeft = 36;
  panel.cornerRadius = 24;
  panel.strokes = [{ type: "SOLID", color: hexToFigmaRgb("#E4E7EC") }];
  panel.fills = [{ type: "SOLID", color: hexToFigmaRgb("#FFFFFF") }];
  const header = visualFrame(`${title} Header`, "VERTICAL", 1184);
  header.itemSpacing = 6;
  header.fills = [];
  header.appendChild(visualText(title, fonts.semiBold, 28, 36, "#111827", 1184));
  if (subtitle) header.appendChild(visualText(subtitle, fonts.medium, 14, 20, "#667085", 1184));
  panel.appendChild(header);
  return panel;
}

function visualFrame(name, mode, width) {
  const frame = figma.createFrame();
  frame.name = name;
  frame.layoutMode = mode;
  frame.fills = [];
  if (width) {
    frame.resize(width, 100);
    frame.primaryAxisSizingMode = mode === "HORIZONTAL" ? "FIXED" : "AUTO";
    frame.counterAxisSizingMode = mode === "HORIZONTAL" ? "AUTO" : "FIXED";
  } else {
    frame.counterAxisSizingMode = "AUTO";
    frame.primaryAxisSizingMode = "AUTO";
  }
  return frame;
}

function groupColorTokens(tokens) {
  const order = ["Brand", "Background", "Neutral", "Overlay", "Semantic", "Auxiliary", "Light", "Dark"];
  const groups = {};
  tokens.forEach((token) => {
    const group = colorGroupName(token.name);
    if (!groups[group]) groups[group] = [];
    groups[group].push(token);
  });
  return Object.fromEntries(
    Object.entries(groups).sort(([a], [b]) => {
      const ai = order.indexOf(a);
      const bi = order.indexOf(b);
      return (ai === -1 ? 99 : ai) - (bi === -1 ? 99 : bi) || a.localeCompare(b);
    }),
  );
}

function colorGroupName(name) {
  const parts = String(name || "").split("/");
  if (["Light", "Dark"].includes(parts[0]) && parts[1]) return parts[1];
  return parts[0] || "Color";
}

function shortTokenName(name) {
  const parts = String(name || "").split("/");
  if (["Light", "Dark"].includes(parts[0])) return `${parts[0]} / ${parts.slice(2).join("/")}`;
  return parts.slice(1).join("/") || name;
}

async function getLocalVariables() {
  if (figma.variables.getLocalVariablesAsync) return await figma.variables.getLocalVariablesAsync();
  return figma.variables.getLocalVariables();
}

async function getLocalCollections() {
  if (figma.variables.getLocalVariableCollectionsAsync) return await figma.variables.getLocalVariableCollectionsAsync();
  return figma.variables.getLocalVariableCollections();
}

async function getLocalPaintStyles() {
  if (figma.getLocalPaintStylesAsync) return await figma.getLocalPaintStylesAsync();
  return figma.getLocalPaintStyles();
}

async function getLocalTextStyles() {
  if (figma.getLocalTextStylesAsync) return await figma.getLocalTextStylesAsync();
  return figma.getLocalTextStyles();
}

async function getLocalEffectStyles() {
  if (figma.getLocalEffectStylesAsync) return await figma.getLocalEffectStylesAsync();
  return figma.getLocalEffectStyles();
}

async function setCurrentPage(page) {
  if (!page) return;
  if (figma.setCurrentPageAsync) {
    await figma.setCurrentPageAsync(page);
    return;
  }
  figma.currentPage = page;
}

async function getOrCreateCollection(name) {
  const collections = await getLocalCollections();
  const existing = collections.find((collection) => collection.name === name);
  if (existing) return existing;
  const collection = figma.variables.createVariableCollection(name);
  trackCreated("collections", collection);
  return collection;
}

async function createVariable(name, collection, type, options = {}) {
  const variables = await getLocalVariables();
  const existing = variables.find((item) => item.name === name && item.variableCollectionId === collection.id);
  if (existing) {
    markPluginOwned(existing);
    return existing;
  }
  try {
    const variable = figma.variables.createVariable(name, collection, type);
    trackCreated("variables", variable);
    markPluginOwned(variable);
    return variable;
  } catch (error) {
    if (options.optional) return null;
    throw error;
  }
}

async function preloadFonts(tokens, availableFonts = []) {
  const plan = tokens.map((token) => {
    const requestedStyle = token.requestedStyle || token.weight || typographyWeightStyle(token.weightRole);
    const resolution = resolveFontMatch({
      family: token.family,
      requestedWeight: token.requestedWeight ?? fontWeightValue(requestedStyle),
      expectedStyle: requestedStyle,
      styleAliases: token.styleAliases || [],
      availableFonts,
    });
    if (resolution.resolutionStatus === "unavailable") {
      throw fontUnavailableError(token.family, requestedStyle);
    }
    return { token, requestedStyle, resolution };
  });
  const uniqueFonts = new Map();
  plan.forEach(({ resolution }) => {
    const fontName = resolution.resolvedFontName;
    uniqueFonts.set(`${fontName.family}\u0000${fontName.style}`, fontName);
  });
  try {
    await Promise.all([...uniqueFonts.values()].map((fontName) => figma.loadFontAsync(fontName)));
  } catch (error) {
    throw fontUnavailableError("Figma Runtime", "loadFontAsync");
  }
  plan.forEach(({ token, requestedStyle, resolution }) => {
    token.requestedFamily = token.requestedFamily || token.family;
    token.requestedStyle = requestedStyle;
    token.resolvedFontName = resolution.resolvedFontName;
    token.resolutionStatus = resolution.resolutionStatus;
    token.wasFallback = resolution.wasFallback;
    token.family = resolution.resolvedFontName.family;
    token.weight = resolution.resolvedFontName.style;
  });
}

function fontUnavailableError(family, style) {
  const error = new Error(`字体不可用：${family} / ${style}。请先在 Figma 中安装或启用这个字体。`);
  error.reasonCode = "FONT_UNAVAILABLE";
  error.fontValidation = [{ reasonCode: "FONT_UNAVAILABLE", state: "error", blocking: true, message: error.message }];
  return error;
}

async function loadFontWithFallback(family, style, availableFonts = []) {
  const fonts = availableFonts.length ? availableFonts : await getAvailableFonts();
  const resolved = resolveFontMatch({
    family,
    requestedWeight: fontWeightValue(style),
    expectedStyle: style,
    styleAliases: [],
    availableFonts: fonts,
  });
  if (resolved.resolutionStatus === "unavailable") throw fontUnavailableError(family, style);
  await figma.loadFontAsync(resolved.resolvedFontName);
  return resolved.resolvedFontName;
}

function fontValidationRequestsFromConfig(config) {
  return [
    {
      id: "primary",
      label: "主字体",
      family: config.primaryFont,
      role: "primary",
      usage: "primary",
      typographyScale: config.typographyScale,
    },
    ...(config.systemType === "lightweight" ? [] : (config.secondaryFonts || []).map((font, index) => ({
      id: `secondary-${index}`,
      label: `副字体 ${index + 1}`,
      family: font.family,
      role: "secondary",
      levels: [...font.levels],
      typographyScale: config.typographyScale,
    }))),
  ];
}

async function runStrictFontPreflight(config) {
  const requests = fontValidationRequestsFromConfig(config);
  const availableFonts = await getAvailableFonts();
  const results = requests.map((request) => validateFontRequest(request, availableFonts, true));
  return {
    requests,
    results,
    availableFonts,
    blocking: results.filter((result) => ["error", "suggestion"].includes(result.state)),
    warnings: results.filter((result) => result.state === "warning"),
  };
}

async function validateFontRequests(requests, strict = false) {
  const availableFonts = await getAvailableFonts();
  return requests.map((request) => validateFontRequest(request, availableFonts, strict));
}

function validationResult(request, profile, overrides = {}) {
  return {
    id: request.id,
    family: String(request.family || "").trim(),
    knownProfile: Boolean(profile),
    approvedLevels: profile?.mappings?.secondary?.recommendedLevels || null,
    levelMode: profile ? "profile" : "manual",
    ...overrides,
  };
}

function validationError(request, profile, reasonCode, message) {
  return validationResult(request, profile, { reasonCode, state: "error", blocking: true, message });
}

function validateFontRequest(request, availableFonts, strict) {
  const family = String(request.family || "").trim();
  const label = String(request.label || "字体");
  const profile = family ? fontProfileForFamily(family) : null;
  if (!family) {
    if (request.role === "secondary") return validationResult(request, null, { state: "inactive", blocking: false, message: "" });
    return validationResult(request, null, {
      state: strict ? "error" : "empty",
      blocking: strict,
      reasonCode: strict ? "PRIMARY_FONT_REQUIRED" : null,
      message: strict ? `${label}需要填写字体名称。` : "",
    });
  }

  if (request.role === "primary" && profile?.eligibility?.primaryUiEligible !== true && profile) {
    return validationError(request, profile, "PRIMARY_FONT_NOT_APPROVED", `${family} 未获批准作为主字体。`);
  }
  if (request.role === "secondary" && profile?.eligibility?.secondaryEligible !== true && profile) {
    return validationError(request, profile, "SECONDARY_FONT_NOT_APPROVED", `${family} 未获批准作为副字体。`);
  }

  const levels = request.role === "secondary"
    ? uniqueFontNames(Array.isArray(request.levels) ? request.levels : [])
    : [];
  if (request.role === "secondary" && levels.length === 0) {
    return validationError(request, profile, "SECONDARY_LEVEL_REQUIRED", "请选择副字体应用层级。");
  }
  if (request.role === "secondary" && profile) {
    const approvedLevels = profile.mappings.secondary?.recommendedLevels || [];
    const unapproved = levels.filter((level) => !approvedLevels.includes(level));
    if (unapproved.length) {
      return validationError(request, profile, "SECONDARY_LEVEL_NOT_APPROVED", `${family} 未批准用于这些层级：${unapproved.join("、")}。`);
    }
  }

  const tokenPlan = fontTokensForRequest({ ...request, family, levels });
  const activeTokens = tokenPlan.filter((token) => !token.skipReasonCode);
  const skippedTokens = tokenPlan.filter((token) => token.skipReasonCode);
  const matches = activeTokens.map((token) => ({
    token,
    match: resolveFontMatch({
      family,
      requestedWeight: token.requestedWeight,
      expectedStyle: token.requestedStyle || token.weight,
      styleAliases: token.styleAliases || [],
      availableFonts,
    }),
  }));
  if (matches.some((item) => item.match.resolutionStatus === "unavailable")) {
    const suggestion = suggestSimilarFontFamily(family, availableFonts);
    if (suggestion) {
      return validationResult(request, profile, {
        state: "suggestion",
        blocking: true,
        reasonCode: "FONT_UNAVAILABLE",
        suggestion,
        message: `未找到“${family}”。是否使用 ${suggestion}？`,
      });
    }
    return validationError(request, profile, "FONT_UNAVAILABLE", `Figma 未找到“${family}”或所需样式。请检查名称或先启用字体。`);
  }

  const resolutions = matches.map(({ token, match }) => ({
    role: token.weightRole,
    requestedStyle: token.requestedStyle,
    requestedWeight: token.requestedWeight,
    ...match,
  }));
  if (request.role === "primary") {
    const requiredRoles = ["baseUi", "emphasis", "strong"];
    const required = requiredRoles.map((role) => resolutions.find((item) => item.role === role)).filter(Boolean);
    const nearest = required.filter((item) => item.resolutionStatus === "nearest");
    const distinct = new Set(required.map((item) => `${item.resolvedFontName.family}/${item.resolvedFontName.style}`));
    if (nearest.length) {
      return validationResult(request, profile, {
        state: "warning",
        blocking: false,
        reasonCode: "PRIMARY_REQUIRED_STYLE_NEAREST",
        runtimeUiEligible: false,
        resolutions,
        message: "主字体必需角色使用了近似字重；Foundation 可以生成，但组件生成将保持禁用。",
      });
    }
    if (required.length < requiredRoles.length || distinct.size < requiredRoles.length) {
      return validationResult(request, profile, {
        state: "warning",
        blocking: false,
        reasonCode: "PRIMARY_REQUIRED_STYLES_COLLAPSED",
        runtimeUiEligible: false,
        resolutions,
        message: "主字体未解析出 Base UI、Emphasis、Strong 三个不同样式；组件生成将保持禁用。",
      });
    }
  }

  if (skippedTokens.length) {
    return validationResult(request, profile, {
      state: "warning",
      blocking: false,
      reasonCode: "SECONDARY_MIN_SIZE_NOT_MET",
      skippedStyles: skippedTokens.map((token) => ({ stylePath: token.name, size: token.size, minRecommendedSizePx: token.minRecommendedSizePx })),
      resolutions,
      message: skippedTokens.map((token) => token.skipMessage).join("\n"),
    });
  }
  if (resolutions.some((item) => item.resolutionStatus === "nearest")) {
    return validationResult(request, profile, {
      state: "fallback",
      blocking: false,
      resolutions,
      message: `已识别为 ${family}，部分样式将使用最接近的可用字重。`,
    });
  }
  if (resolutions.some((item) => item.resolutionStatus === "style-alias") || resolutions.some((item) => item.familyMatch !== "exact")) {
    return validationResult(request, profile, {
      state: "normalized",
      blocking: false,
      resolutions,
      message: `已识别为 ${uniqueFontNames(resolutions.map((item) => item.resolvedFontName.family)).join("、")}。`,
    });
  }
  return validationResult(request, profile, { state: "valid", blocking: false, resolutions, message: "当前 Figma 可用。" });
}

function fontTokensForRequest(request) {
  const preset = typographyDefinitions(request.typographyScale);
  if (request.role === "secondary") {
    return secondaryTypographyTokens({ family: request.family, levels: request.levels || [] }, 0, preset, request.typographyScale);
  }
  const profile = fontProfileForFamily(request.family);
  return preset.map((definition) => {
    const mapping = primaryFontMapping(definition.weightRole, profile);
    return {
      ...definition,
      family: request.family,
      weightRole: definition.weightRole,
      requestedStyle: mapping.expectedStyle,
      requestedWeight: mapping.requestedWeight,
      styleAliases: mapping.styleAliases,
    };
  });
}

function fontStylesForRequest(request) {
  return uniqueFontNames(fontTokensForRequest(request).filter((token) => !token.skipReasonCode).map((token) => token.requestedStyle || token.weight));
}

function resolveFontMatch({ family, requestedWeight, expectedStyle, styleAliases = [], availableFonts = [] }) {
  const matchedFamily = matchFontFamily(family, availableFonts);
  const familyCandidates = uniqueFontNames([matchedFamily, String(family || "").trim()]);
  for (const fontFamily of familyCandidates) {
    const availableStyles = availableFonts
      .filter((font) => font.fontName.family === fontFamily && !isItalicFontStyle(font.fontName.style))
      .map((font) => font.fontName.style);
    if (!availableStyles.length) continue;
    const exact = availableStyles.find((style) => style === expectedStyle);
    if (exact) return fontResolution(fontFamily, exact, family, "exact");
    for (const alias of styleAliases) {
      const match = findFontStyle(alias, availableStyles);
      if (match) return fontResolution(fontFamily, match, family, "style-alias");
    }
    const sameWeightAliases = (FONT_STYLE_FALLBACKS[fontStyleGroup(expectedStyle)] || [])
      .filter((alias) => fontWeightValue(alias) === Number(requestedWeight));
    for (const alias of sameWeightAliases) {
      const match = findFontStyle(alias, availableStyles);
      if (match) return fontResolution(fontFamily, match, family, "style-alias");
    }
    for (const candidate of fontStyleCandidates(expectedStyle)) {
      const match = findFontStyle(candidate, availableStyles);
      if (match) return fontResolution(fontFamily, match, family, "nearest");
    }
  }

  const embeddedFamilyFont = matchEmbeddedFamilyFont(family, fontStyleCandidates(expectedStyle), availableFonts);
  if (embeddedFamilyFont) {
    const status = fontStyleMatchesRequested(expectedStyle, embeddedFamilyFont.style) ? "style-alias" : "nearest";
    return {
      resolvedFontName: embeddedFamilyFont,
      resolutionStatus: status,
      familyMatch: "series",
      wasFallback: status === "nearest",
    };
  }
  return { resolvedFontName: null, resolutionStatus: "unavailable", familyMatch: "none", wasFallback: false };
}

function findFontStyle(candidate, availableStyles) {
  return availableStyles.find((style) => style === candidate)
    || availableStyles.find((style) => normalizeFontKey(style) === normalizeFontKey(candidate))
    || "";
}

function fontResolution(fontFamily, style, requestedFamily, resolutionStatus) {
  return {
    resolvedFontName: { family: fontFamily, style },
    resolutionStatus,
    familyMatch: fontFamily === String(requestedFamily || "").trim() ? "exact" : "normalized",
    wasFallback: resolutionStatus === "nearest",
  };
}

function classifyFontStyleMatch(requested, resolved) {
  if (normalizeFontKey(requested) === normalizeFontKey(resolved)) return "exact";
  if (isRecognizedFontStyle(requested) && isRecognizedFontStyle(resolved) && fontStyleGroup(requested) === fontStyleGroup(resolved)) {
    return "style-alias";
  }
  return "nearest";
}

function fontStyleMatchesRequested(requested, resolved) {
  if (normalizeFontKey(requested) === normalizeFontKey(resolved)) return true;
  return isRecognizedFontStyle(requested) && isRecognizedFontStyle(resolved) && fontStyleGroup(requested) === fontStyleGroup(resolved);
}

function suggestSimilarFontFamily(family, availableFonts) {
  const target = normalizeFontKey(family);
  if (target.length < 3) return "";
  const candidates = [...new Set(availableFonts.map((font) => font.fontName.family))]
    .filter((name) => fontFamilyBaseKey(name) === normalizeFontKey(name))
    .map((name) => ({ name, distance: levenshteinDistance(target, normalizeFontKey(name)) }))
    .filter((candidate) => candidate.distance <= maximumFontSuggestionDistance(target.length, normalizeFontKey(candidate.name).length))
    .sort((left, right) => left.distance - right.distance || left.name.localeCompare(right.name));
  return candidates[0]?.name || "";
}

function maximumFontSuggestionDistance(leftLength, rightLength) {
  const length = Math.max(leftLength, rightLength);
  if (length <= 4) return 1;
  if (length <= 8) return 2;
  return Math.max(2, Math.floor(length * 0.22));
}

function levenshteinDistance(left, right) {
  const previous = Array.from({ length: right.length + 1 }, (_, index) => index);
  for (let leftIndex = 1; leftIndex <= left.length; leftIndex += 1) {
    let diagonal = previous[0];
    previous[0] = leftIndex;
    for (let rightIndex = 1; rightIndex <= right.length; rightIndex += 1) {
      const above = previous[rightIndex];
      previous[rightIndex] = Math.min(
        previous[rightIndex] + 1,
        previous[rightIndex - 1] + 1,
        diagonal + (left[leftIndex - 1] === right[rightIndex - 1] ? 0 : 1),
      );
      diagonal = above;
    }
  }
  return previous[right.length];
}

function uniqueFontNames(values) {
  return [...new Set(values.filter(Boolean))];
}

async function getAvailableFonts() {
  try {
    return await figma.listAvailableFontsAsync();
  } catch (error) {
    return [];
  }
}

function matchFontFamily(family, availableFonts) {
  const target = normalizeFontKey(family);
  const match = availableFonts.find((font) => normalizeFontKey(font.fontName.family) === target);
  return match ? match.fontName.family : "";
}

function matchFontStyle(candidates, styles) {
  const availableStyles = candidates.some((candidate) => isItalicFontStyle(candidate))
    ? styles
    : styles.filter((style) => !isItalicFontStyle(style));
  for (const candidate of candidates) {
    const direct = availableStyles.find((style) => style === candidate);
    if (direct) return direct;
    const normalized = normalizeFontKey(candidate);
    const loose = availableStyles.find((style) => normalizeFontKey(style) === normalized);
    if (loose) return loose;
    const group = fontStyleGroup(candidate);
    const grouped = availableStyles.find((style) => isRecognizedFontStyle(style) && fontStyleGroup(style) === group);
    if (grouped) return grouped;
  }
  return "";
}

function normalizeFontKey(value) {
  return String(value || "")
    .toLowerCase()
    .replace(/[^0-9a-z\u00c0-\u024f\u0370-\u1fff\u2c00-\u2dff\u3040-\u30ff\u3130-\ud7af\u3400-\u9fff]+/gi, "");
}

function fontStyleCandidates(style) {
  const requested = String(style || "Regular").trim() || "Regular";
  const candidates = [requested, ...(FONT_STYLE_FALLBACKS[fontStyleGroup(requested)] || FONT_STYLE_FALLBACKS.regular)];
  const seen = new Set();
  return candidates.filter((candidate) => {
    const key = normalizeFontKey(candidate);
    if (!key || seen.has(key)) return false;
    seen.add(key);
    return true;
  });
}

function fontWeightValue(weight) {
  const group = fontStyleGroup(weight);
  if (group === "thin") return 100;
  if (group === "light") return 300;
  if (group === "medium") return 500;
  if (group === "semibold") return 600;
  if (group === "bold") return 700;
  if (group === "extrabold") return 800;
  if (group === "black") return 900;
  return 400;
}

function fontStyleGroup(style) {
  const key = normalizeFontKey(style);
  if (key.includes("extrablack") || key.includes("ultrablack") || key.includes("black") || key.includes("heavy") || /^(?:w?900)$/.test(key)) return "black";
  if (key.includes("extrabold") || key.includes("ultrabold") || /^(?:w?800)$/.test(key)) return "extrabold";
  if (key.includes("semibold") || key.includes("demibold") || /^(?:w?600)$/.test(key)) return "semibold";
  if (key.includes("bold") || /^(?:w?700)$/.test(key)) return "bold";
  if (key.includes("medium") || /^(?:w?500)$/.test(key)) return "medium";
  if (key.includes("extralight") || key.includes("ultralight") || /^(?:w?200)$/.test(key)) return "light";
  if (key.includes("thin") || /^(?:w?100)$/.test(key)) return "thin";
  if (key.includes("light") || /^(?:w?300)$/.test(key)) return "light";
  return "regular";
}

function isRecognizedFontStyle(style) {
  const key = normalizeFontKey(style);
  return /(?:thin|light|regular|normal|plain|book|roman|medium|semibold|demibold|bold|black|heavy|w?[1-9]00)/.test(key);
}

function isItalicFontStyle(style) {
  return /(?:italic|oblique)/i.test(String(style || ""));
}

function matchEmbeddedFamilyFont(family, styleCandidates, availableFonts) {
  const baseKey = fontFamilyBaseKey(family);
  if (!baseKey) return null;
  const allowsItalic = styleCandidates.some((candidate) => isItalicFontStyle(candidate));
  const matches = availableFonts
    .map((font) => font.fontName)
    .filter((fontName) => {
      const isItalic = isItalicFontStyle(fontName.family) || isItalicFontStyle(fontName.style);
      return fontFamilyBaseKey(fontName.family) === baseKey && (allowsItalic || !isItalic);
    })
    .sort((left, right) => {
      const candidateDelta = embeddedFamilyMatchRank(left, styleCandidates) - embeddedFamilyMatchRank(right, styleCandidates);
      if (candidateDelta) return candidateDelta;
      const widthDelta = Number(fontFamilyHasWidthModifier(left.family)) - Number(fontFamilyHasWidthModifier(right.family));
      if (widthDelta) return widthDelta;
      return `${left.family}/${left.style}`.localeCompare(`${right.family}/${right.style}`);
    });
  return matches[0] || null;
}

function embeddedFamilyMatchRank(fontName, styleCandidates) {
  const familyVariants = fontVariantKeys(fontName.family);
  const styleVariants = fontVariantKeys(fontName.style);
  for (let index = 0; index < styleCandidates.length; index += 1) {
    if (familyVariants.has(normalizeFontKey(styleCandidates[index]))) return index;
  }
  for (let index = 0; index < styleCandidates.length; index += 1) {
    if (styleVariants.has(normalizeFontKey(styleCandidates[index]))) return styleCandidates.length + index;
  }
  return styleCandidates.length * 2;
}

function fontFamilyBaseKey(family) {
  let key = normalizeFontKey(family);
  let matchedSuffix = true;
  while (matchedSuffix && key) {
    matchedSuffix = false;
    for (const suffix of FONT_FAMILY_VARIANT_SUFFIXES) {
      if (key.length > suffix.length && key.endsWith(suffix)) {
        key = key.slice(0, -suffix.length);
        matchedSuffix = true;
        break;
      }
    }
  }
  return key;
}

function fontVariantKeys(value) {
  const key = normalizeFontKey(value);
  const variants = new Set();
  for (const suffix of FONT_FAMILY_VARIANT_SUFFIXES) {
    if (key.endsWith(suffix)) {
      variants.add(suffix);
      break;
    }
  }
  if (/^(?:w?[1-9]00)$/.test(key)) variants.add(fontStyleGroup(key));
  return variants;
}

function fontFamilyHasWidthModifier(family) {
  const key = normalizeFontKey(family);
  return ["condensed", "compressed", "narrow", "extended", "expanded", "wide"].some((modifier) => key.includes(modifier));
}

function tokenToSolidPaint(token) {
  return {
    type: "SOLID",
    color: hexToFigmaRgb(token.value),
    opacity: token.opacity === undefined ? 1 : token.opacity,
  };
}

function gradientToPaint(token) {
  return {
    type: gradientPaintType(token.direction),
    gradientTransform: gradientTransform(token.direction),
    gradientStops: [
      { position: 0, color: { ...hexToFigmaRgb(token.from), a: 1 } },
      { position: 1, color: { ...hexToFigmaRgb(token.to), a: 1 } },
    ],
  };
}

function gradientPaintType(type) {
  if (type === "radial") return "GRADIENT_RADIAL";
  if (type === "angular") return "GRADIENT_ANGULAR";
  if (type === "diamond") return "GRADIENT_DIAMOND";
  return "GRADIENT_LINEAR";
}

function gradientTransform(type) {
  const direction = ["left-right", "top-bottom", "diagonal"].includes(type) ? type : "left-right";
  if (direction === "top-bottom") {
    return [
      [0, 1, 0],
      [-1, 0, 1],
    ];
  }
  if (direction === "diagonal") {
    return [
      [0.707, 0.707, -0.207],
      [-0.707, 0.707, 0.5],
    ];
  }
  return [
    [1, 0, 0],
    [0, 1, 0],
  ];
}

function paintToVariableValue(token) {
  const rgb = hexToFigmaRgb(token.value);
  return {
    r: rgb.r,
    g: rgb.g,
    b: rgb.b,
    a: token.opacity === undefined ? 1 : token.opacity,
  };
}

function rgbaToFigmaColor(value) {
  const match = String(value).match(/rgba\((\d+),\s*(\d+),\s*(\d+),\s*([0-9.]+)\)/);
  if (!match) {
    const rgb = hexToFigmaRgb(value);
    return { ...rgb, a: 1 };
  }
  return {
    r: Number(match[1]) / 255,
    g: Number(match[2]) / 255,
    b: Number(match[3]) / 255,
    a: Number(match[4]),
  };
}

function hexToFigmaRgb(hex) {
  const rgb = hexToRgb(hex);
  return { r: rgb.r / 255, g: rgb.g / 255, b: rgb.b / 255 };
}

function figmaColorToHex(color) {
  return rgbToHex({
    r: color.r * 255,
    g: color.g * 255,
    b: color.b * 255,
  });
}

function normalizeHex(value, fallback) {
  const raw = String(value || "").trim().replace(/^#/, "");
  if (/^[0-9a-fA-F]{3}$/.test(raw)) {
    return `#${raw.split("").map((char) => char + char).join("").toUpperCase()}`;
  }
  if (/^[0-9a-fA-F]{6}$/.test(raw)) return `#${raw.toUpperCase()}`;
  return fallback;
}

function hasValidHex(value) {
  const raw = String(value || "").trim().replace(/^#/, "");
  return /^[0-9a-fA-F]{3}$/.test(raw) || /^[0-9a-fA-F]{6}$/.test(raw);
}

function sanitizeTokenSegment(value) {
  const segment = String(value || "")
    .trim()
    .replace(/[\\/]+/g, "-")
    .replace(/\s+/g, "-")
    .replace(/^-+|-+$/g, "");
  return segment || "item";
}

function sanitizeModeName(value) {
  const name = String(value || "")
    .trim()
    .replace(/[\\/]+/g, "-")
    .replace(/\s+/g, " ");
  return name || "Theme";
}

function uniqueNames(names) {
  const seen = new Map();
  return names.map((name) => {
    const base = name || "Theme";
    const count = (seen.get(base) || 0) + 1;
    seen.set(base, count);
    return count === 1 ? base : `${base} ${count}`;
  });
}

function uniquifyThemeNames(themes) {
  const names = uniqueNames(themes.map((theme, index) => theme.name || `Theme ${index + 1}`));
  return themes.map((theme, index) => ({ ...theme, name: names[index] }));
}

function colorRef(name) {
  if (name === "white") return RULES.white;
  if (name === "darkAnchor") return RULES.darkAnchor;
  return name;
}

function hexToRgb(hex) {
  const clean = normalizeHex(hex, "#000000").slice(1);
  return {
    r: parseInt(clean.slice(0, 2), 16),
    g: parseInt(clean.slice(2, 4), 16),
    b: parseInt(clean.slice(4, 6), 16),
  };
}

function rgbToHex({ r, g, b }) {
  return `#${[r, g, b]
    .map((value) => Math.max(0, Math.min(255, Math.round(value))).toString(16).padStart(2, "0"))
    .join("")
    .toUpperCase()}`;
}

function rgbToHsl({ r, g, b }) {
  const red = r / 255;
  const green = g / 255;
  const blue = b / 255;
  const max = Math.max(red, green, blue);
  const min = Math.min(red, green, blue);
  const lightness = (max + min) / 2;
  const delta = max - min;
  if (delta === 0) return { h: 0, s: 0, l: lightness };

  const saturation = delta / (1 - Math.abs(2 * lightness - 1));
  let hue;
  if (max === red) hue = ((green - blue) / delta) % 6;
  else if (max === green) hue = (blue - red) / delta + 2;
  else hue = (red - green) / delta + 4;
  hue *= 60;
  if (hue < 0) hue += 360;
  return { h: hue, s: saturation, l: lightness };
}

function hslToHex({ h, s, l }) {
  const chroma = (1 - Math.abs(2 * l - 1)) * s;
  const x = chroma * (1 - Math.abs(((h / 60) % 2) - 1));
  const m = l - chroma / 2;
  let r = 0;
  let g = 0;
  let b = 0;
  if (h < 60) [r, g, b] = [chroma, x, 0];
  else if (h < 120) [r, g, b] = [x, chroma, 0];
  else if (h < 180) [r, g, b] = [0, chroma, x];
  else if (h < 240) [r, g, b] = [0, x, chroma];
  else if (h < 300) [r, g, b] = [x, 0, chroma];
  else [r, g, b] = [chroma, 0, x];
  return rgbToHex({ r: (r + m) * 255, g: (g + m) * 255, b: (b + m) * 255 });
}

function hexToHsl(hex) {
  return rgbToHsl(hexToRgb(hex));
}

function hexToOklch(hex) {
  const rgb = hexToRgb(hex);
  const r = srgbToLinear(rgb.r / 255);
  const g = srgbToLinear(rgb.g / 255);
  const b = srgbToLinear(rgb.b / 255);
  const l = Math.cbrt(0.4122214708 * r + 0.5363325363 * g + 0.0514459929 * b);
  const m = Math.cbrt(0.2119034982 * r + 0.6806995451 * g + 0.1073969566 * b);
  const s = Math.cbrt(0.0883024619 * r + 0.2817188376 * g + 0.6299787005 * b);
  const okL = 0.2104542553 * l + 0.793617785 * m - 0.0040720468 * s;
  const okA = 1.9779984951 * l - 2.428592205 * m + 0.4505937099 * s;
  const okB = 0.0259040371 * l + 0.7827717662 * m - 0.808675766 * s;
  const chroma = Math.sqrt(okA * okA + okB * okB);
  const hue = ((Math.atan2(okB, okA) * 180) / Math.PI + 360) % 360;
  return { l: okL, c: chroma, h: hue };
}

function oklchToHex({ l, c, h }) {
  const hue = (h * Math.PI) / 180;
  const a = c * Math.cos(hue);
  const b = c * Math.sin(hue);
  const lPrime = l + 0.3963377774 * a + 0.2158037573 * b;
  const mPrime = l - 0.1055613458 * a - 0.0638541728 * b;
  const sPrime = l - 0.0894841775 * a - 1.291485548 * b;
  const lCube = lPrime * lPrime * lPrime;
  const mCube = mPrime * mPrime * mPrime;
  const sCube = sPrime * sPrime * sPrime;
  const r = linearToSrgb(4.0767416621 * lCube - 3.3077115913 * mCube + 0.2309699292 * sCube);
  const g = linearToSrgb(-1.2684380046 * lCube + 2.6097574011 * mCube - 0.3413193965 * sCube);
  const blue = linearToSrgb(-0.0041960863 * lCube - 0.7034186147 * mCube + 1.707614701 * sCube);
  return rgbToHex({ r: r * 255, g: g * 255, b: blue * 255 });
}

function srgbToLinear(value) {
  return value <= 0.04045 ? value / 12.92 : ((value + 0.055) / 1.055) ** 2.4;
}

function linearToSrgb(value) {
  const clamped = clamp(value, 0, 1);
  return clamped <= 0.0031308 ? clamped * 12.92 : 1.055 * clamped ** (1 / 2.4) - 0.055;
}

function mix(hexA, hexB, amount) {
  const a = hexToRgb(hexA);
  const b = hexToRgb(hexB);
  return rgbToHex({
    r: a.r + (b.r - a.r) * amount,
    g: a.g + (b.g - a.g) * amount,
    b: a.b + (b.b - a.b) * amount,
  });
}

function rgbaString(hex, alpha) {
  const rgb = hexToRgb(hex);
  return `rgba(${rgb.r}, ${rgb.g}, ${rgb.b}, ${Number(alpha.toFixed(2))})`;
}

function clamp(value, min, max) {
  return Math.max(min, Math.min(max, value));
}

function buildDeveloperExportFiles(system, manifest, inventory) {
  const data = buildDeveloperExportData(system, manifest, inventory);
  const baseName = exportFilenameBase(system.config.projectCode);

  return {
    files: [
      {
        filename: `${baseName}-Design-System.md`,
        mimeType: "text/markdown;charset=utf-8",
        content: renderDeveloperMarkdown(data),
      },
      {
        filename: `${baseName}-Design-System.json`,
        mimeType: "application/json;charset=utf-8",
        content: `${JSON.stringify(data, null, 2)}\n`,
      },
    ],
  };
}

function buildDeveloperExportData(system, manifest, inventory) {
  const modes = [...(manifest.modeNames || [])];
  const projectPrefix = `${system.config.projectCode}/`;
  const semanticEntries = Object.entries(manifest.resources.colors || {});
  const semanticAliasLocatorKeys = new Set(
    semanticEntries
      .filter(([, resource]) => resource.bindingStrategy === "semantic-alias")
      .map(([, resource]) => resourceLocatorIdentity(resource.binding)),
  );
  const actualColorVariables = inventory.variables
    .filter((variable) => variable.resolvedType === "COLOR" && variable.name.startsWith(projectPrefix))
    .map((variable) => serializeActualColorVariable(variable, modes, inventory));
  const semanticColors = semanticEntries.map(([role, resource]) => {
    const binding = resource.binding || resource;
    const matches = inventory.variablesByLocator.get(resourceLocatorKey(binding.collectionName, binding.variablePath)) || [];
    const serialized = matches[0]
      ? serializeActualColorVariable(matches[0], modes, inventory)
      : { name: binding.variablePath || "", type: binding.variableType || "COLOR", values: {}, aliasSources: {} };
    return {
      ...serialized,
      role,
      bindingStrategy: resource.bindingStrategy || "direct",
      binding,
      sourcesByMode: resource.sourcesByMode || {},
      sharedBinding: resource.sharedBinding || "",
    };
  });
  const foundationColors = actualColorVariables.filter((item) => {
    const variable = inventory.variables.find((candidate) => candidate.name === item.name && candidate.resolvedType === "COLOR");
    if (!variable) return true;
    const collection = inventory.collectionById.get(variable.variableCollectionId);
    return !semanticAliasLocatorKeys.has(resourceLocatorIdentity({
      collectionName: collection?.name || "",
      variablePath: variable.name,
      variableType: variable.resolvedType,
    }));
  });
  const typography = inventory.textStyles
    .filter((style) => isPluginOwned(style))
    .map((style) => ({
      name: style.name,
      family: style.fontName?.family || "",
      weight: style.fontName?.style || "",
      size: normalizeStableValue(style.fontSize),
      lineHeight: normalizeStableValue(style.lineHeight),
      letterSpacing: normalizeStableValue(style.letterSpacing),
    }))
    .sort((left, right) => left.name.localeCompare(right.name));
  const dimensions = inventory.variables
    .filter((variable) => variable.resolvedType === "FLOAT" && variable.name.startsWith(projectPrefix))
    .map((variable) => serializeActualDimensionVariable(variable, inventory))
    .sort((left, right) => left.name.localeCompare(right.name));
  return {
    formatVersion: "1.2.0",
    generatedBy: "Design System Builder",
    generatorVersion: GENERATOR_VERSION,
    generatedAt: manifest.generatedAt,
    projectCode: system.config.projectCode || "",
    systemType: system.config.systemType || "standard",
    typographyScale: system.config.typographyScale || "standard",
    colorModes: modes,
    foundationColors,
    semanticColors,
    gradients: inventory.paintStyles
      .filter((style) => isPluginOwned(style))
      .map((style) => ({ name: style.name, paints: normalizeStableValue(style.paints || []) }))
      .sort((left, right) => left.name.localeCompare(right.name)),
    typography,
    typographyManifest: manifest.typography,
    shadows: inventory.effectStyles
      .filter((style) => isPluginOwned(style))
      .map((style) => ({ name: style.name, effects: normalizeStableValue(style.effects || []) }))
      .sort((left, right) => left.name.localeCompare(right.name)),
    radius: dimensions.filter((item) => item.name.includes("/Radius/")),
    spacing: dimensions.filter((item) => item.name.includes("/Spacing/")),
    semanticManifest: manifest,
  };
}

function serializeActualColorVariable(variable, modes, inventory) {
  const collection = inventory.collectionById.get(variable.variableCollectionId);
  const finalModes = modes.length ? modes : (collection?.modes || []).map((mode) => mode.name);
  return {
    name: variable.name,
    type: variable.resolvedType,
    values: Object.fromEntries(
      finalModes.map((modeName) => [modeName, formatResolvedColorValue(resolveVariableValueByMode(variable, modeName, inventory))]),
    ),
    aliasSources: Object.fromEntries(
      finalModes.map((modeName) => [modeName, aliasSourceForMode(variable, modeName, inventory)]),
    ),
  };
}

function serializeActualDimensionVariable(variable, inventory) {
  const collection = inventory.collectionById.get(variable.variableCollectionId);
  const mode = collection?.modes?.[0];
  return {
    name: variable.name,
    value: mode ? normalizeStableValue(resolveVariableValueByMode(variable, mode.name, inventory)) : null,
  };
}

function resolveVariableValueByMode(variable, modeName, inventory, visited = new Set()) {
  if (!variable || visited.has(variable.id)) return null;
  visited.add(variable.id);
  const collection = inventory.collectionById.get(variable.variableCollectionId);
  const mode = (collection?.modes || []).find((item) => item.name === modeName) || collection?.modes?.[0];
  if (!mode) return null;
  const value = variable.valuesByMode?.[mode.modeId];
  if (value && value.type === "VARIABLE_ALIAS") {
    return resolveVariableValueByMode(inventory.variableById.get(value.id), modeName, inventory, visited);
  }
  return value;
}

function aliasSourceForMode(variable, modeName, inventory) {
  const collection = inventory.collectionById.get(variable.variableCollectionId);
  const mode = (collection?.modes || []).find((item) => item.name === modeName) || collection?.modes?.[0];
  const value = mode ? variable.valuesByMode?.[mode.modeId] : null;
  if (!value || value.type !== "VARIABLE_ALIAS") return "";
  const source = inventory.variableById.get(value.id);
  const sourceCollection = source ? inventory.collectionById.get(source.variableCollectionId) : null;
  return source ? `${sourceCollection?.name || ""} / ${source.name}` : "";
}

function formatResolvedColorValue(value) {
  if (!value || typeof value !== "object" || value.r === undefined) return "";
  const hex = figmaColorToHex(value);
  const opacity = value.a === undefined || value.a === 1 ? "" : ` / ${Math.round(value.a * 100)}%`;
  return `${hex}${opacity}`;
}

function renderDeveloperMarkdown(data) {
  const title = data.projectCode
    ? `${data.projectCode} Design System`
    : "Design System";
  const modes = data.colorModes.length ? data.colorModes.join(", ") : "Default";
  const lines = [
    `# ${title}`,
    "",
    `- Generator version: ${data.generatorVersion}`,
    `- Generated at: ${data.generatedAt}`,
    `- System type: ${data.systemType}`,
    `- Typography scale: ${data.typographyScale}`,
    `- Modes: ${modes}`,
    `- Manifest status: ${data.semanticManifest.status}`,
    `- System revision: ${data.semanticManifest.systemRevision}`,
    "",
    "## Foundation Colors",
    ...renderColorTable(data.foundationColors, data.colorModes),
    "",
    "## Semantic Colors",
    ...renderSemanticColorTable(data.semanticColors, data.colorModes),
    "",
    "## Gradients",
    ...renderGradientTable(data.gradients),
    "",
    "## Typography",
    ...renderTypographyTable(data.typography),
    "",
    "## Shadows",
    ...renderShadowList(data.shadows),
    "",
    "## Radius",
    ...renderDimensionTable(data.radius, "Token"),
    "",
    "## Spacing",
    ...renderDimensionTable(data.spacing, "Token"),
    "",
    "## Semantic Role Mapping",
    ...renderSemanticResourceMapping(data.semanticManifest.resources),
    "",
    "## Front-end Usage",
    "",
    "- Resolve resources by semantic role and stable path; do not persist Figma Variable, Style, or Mode IDs.",
    "- Treat the Semantic Token Manifest as the lookup contract and validate the current Figma file before generating components.",
    "- Do not substitute missing roles with visually similar colors or component-local tokens.",
    "",
  ];
  return lines.join("\n");
}

function renderColorTable(tokens, modes) {
  const columns = modes.length ? modes : ["Default"];
  if (!tokens.length) return ["No color tokens generated."];
  return [
    markdownTableRow(["Token"].concat(columns)),
    markdownTableRow(["---"].concat(columns.map(() => "---"))),
    ...tokens.map((token) =>
      markdownTableRow([
        `\`${token.name}\``,
        ...columns.map((mode) => token.values[mode] || "-"),
      ]),
    ),
  ];
}

function renderSemanticColorTable(tokens, modes) {
  const columns = modes.length ? modes : ["Default"];
  if (!tokens.length) return ["No semantic color roles generated."];
  return [
    markdownTableRow(["Semantic Role", "Strategy", "Binding", "Type"].concat(columns, ["Sources by Mode"])),
    markdownTableRow(["---", "---", "---", "---"].concat(columns.map(() => "---"), ["---"])),
    ...tokens.map((token) => markdownTableRow([
      `\`${token.role}\``,
      token.bindingStrategy,
      `\`${formatResourceLocator(token.binding)}\``,
      token.type,
      ...columns.map((mode) => token.values[mode] || "-"),
      columns.map((mode) => `${mode}: ${formatResourceLocator(token.sourcesByMode?.[mode])}`).join("; "),
    ])),
  ];
}

function renderGradientTable(tokens) {
  if (!tokens.length) return ["No gradient styles generated."];
  return [
    markdownTableRow(["Token", "Type", "Direction", "Stops", "Fallback"]),
    markdownTableRow(["---", "---", "---", "---", "---"]),
    ...tokens.map((token) =>
      markdownTableRow([
        `\`${token.name}\``,
        token.paints?.[0]?.type || "-",
        "-",
        JSON.stringify(token.paints?.[0]?.gradientStops || []),
        "-",
      ]),
    ),
  ];
}

function renderTypographyTable(tokens) {
  if (!tokens.length) return ["No text styles generated."];
  return [
    markdownTableRow(["Style", "Font family", "Weight", "Size / line", "Letter spacing"]),
    markdownTableRow(["---", "---", "---", "---", "---"]),
    ...tokens.map((token) =>
      markdownTableRow([
        `\`${token.name}\``,
        token.family,
        token.weight,
        `${token.size}px / ${formatStyleValue(token.lineHeight)}`,
        formatStyleValue(token.letterSpacing),
      ]),
    ),
  ];
}

function renderShadowList(tokens) {
  if (!tokens.length) return ["No effect styles generated."];
  return tokens.flatMap((token) => [
    `### \`${token.name}\``,
    ...(token.effects.length
      ? token.effects.map((effect) => `- \`${markdownCell(JSON.stringify(effect))}\``)
      : ["- No shadow layers"]),
    "",
  ]);
}

function renderDimensionTable(tokens, label) {
  if (!tokens.length) return [`No ${label.toLowerCase()} tokens generated.`];
  return [
    markdownTableRow([label, "Value"]),
    markdownTableRow(["---", "---"]),
    ...tokens.map((token) => markdownTableRow([`\`${token.name}\``, `${token.value}px`])),
  ];
}

function renderSemanticResourceMapping(resources) {
  const rows = [];
  for (const [category, entries] of Object.entries(resources || {})) {
    for (const [role, locator] of Object.entries(entries || {})) {
      const isColor = category === "colors" && locator.binding;
      const resource = isColor ? locator.binding : locator;
      rows.push([
        `\`${role}\``,
        category,
        isColor ? locator.bindingStrategy : "-",
        `\`${formatResourceLocator(resource)}\``,
        resource.variableType || resource.resourceType || "-",
        isColor
          ? Object.entries(locator.sourcesByMode || {}).map(([modeName, source]) => `${modeName}: ${formatResourceLocator(source)}`).join("; ")
          : "-",
      ]);
    }
  }
  if (!rows.length) return ["No semantic resources generated."];
  return [
    markdownTableRow(["Semantic Role", "Category", "Strategy", "Resource", "Type", "Sources by Mode"]),
    markdownTableRow(["---", "---", "---", "---", "---", "---"]),
    ...rows.map(markdownTableRow),
  ];
}

function formatResourceLocator(locator) {
  if (!locator) return "-";
  if (locator.variablePath) return `${locator.collectionName || ""} / ${locator.variablePath}`;
  return locator.stylePath || "-";
}

function formatStyleValue(value) {
  if (value == null) return "-";
  if (typeof value === "number") return `${value}px`;
  if (typeof value === "object" && value.value !== undefined) return `${value.value}${value.unit === "PIXELS" ? "px" : value.unit || ""}`;
  return JSON.stringify(value);
}

function markdownTableRow(cells) {
  return `| ${cells.map(markdownCell).join(" | ")} |`;
}

function markdownCell(value) {
  return String(value == null ? "-" : value)
    .replace(/\|/g, "\\|")
    .replace(/[\r\n]+/g, " ");
}

function exportFilenameBase(projectCode) {
  const value = String(projectCode || "design-system")
    .trim()
    .replace(/[^a-z0-9._-]+/gi, "-")
    .replace(/^-+|-+$/g, "");
  return value || "design-system";
}

function summarizeResult(result) {
  return [
    `颜色变量：${result.colorVariables}`,
    `语义 Alias：${result.semanticVariables || 0}`,
    `颜色样式：${result.colorStyles}`,
	    `渐变样式：${result.gradientStyles}`,
	    `数值变量：${result.numberVariables}`,
	    `字体变量：${result.typographyVariables}`,
	    `字体样式：${result.textStyles}`,
    `阴影样式：${result.effectStyles}`,
    `可视化节点：${result.visualNodes}`,
  ].join("\n");
}
